class FfiConverterTypeAccount: FfiConverter<Account, ulong> {
    public static FfiConverterTypeAccount INSTANCE = new FfiConverterTypeAccount();


    public override ulong Lower(Account value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override Account Lift(ulong value) {
        return new Account(value);
    }

    public override Account Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(Account value) {
        return 8;
    }

    public override void Write(Account value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
}



