        CallWithPointer(thisPtr => {
            return _UniFFILib.uniffi_scaas_sdk_fn_method_confidential_pqz_balance(thisPtr, FfiConverterTypePqzBalanceRequest.INSTANCE.Lower(@r));
        }),
        // Poll
