/// <summary>
/// The app's authenticator (spec §6.10) as a foreign async interface. A PRF output or platform secret is written by the app
/// through the copy calls into the secret whose id it is given (`prf_out`, `out`). A foreign exception arrives as
/// `AuthError::Unexpected`.
/// </summary>
internal interface ForeignAuthenticator {
    /// <exception cref="AuthException"></exception>
    Task<PasskeyCreated> CreatePasskey(string @rpId, string @userName, byte[][] @exclude);
    /// <exception cref="AuthException"></exception>
    Task<Assertion> GetAssertion(AssertionRequest @req, ulong @prfOut);
    /// <summary>
    /// `key_handle`: the platform key's handle (the Rust trait's `handle`; named apart from the generated callbacks' own local
    /// `handle`, which uniffi-bindgen-cs and -go do not rename)
    /// </summary>
    /// <exception cref="AuthException"></exception>
    Task PlatformSecret(string @keyHandle, byte[] @salt, string @reason, KeyPolicy? @policy, ulong @out);
    /// <exception cref="AuthException"></exception>
    Task<SePublic> P256Generate(KeyPolicy @policy);
    /// <exception cref="AuthException"></exception>
    Task<byte[]> P256Sign(string @keyHandle, byte[] @uaMsg, string @reason);
