    public override ulong Lower(ForeignAuthenticator value) {
        if (value is ForeignAuthenticatorImpl rustObj) {
            // Rust-implemented object. Clone the handle and return it.
            return rustObj.CallWithPointer(thisPtr => thisPtr);
        } else {
            // C# object, generate a new handle map entry and return it.
            return handleMap.Insert(value);
        }
    }

    public override ForeignAuthenticator Lift(ulong value) {
        if ((value & 1UL) == 0UL) {
            // Rust-generated handle, construct a new wrapper.
            return new ForeignAuthenticatorImpl(value);
        } else {
            // C#-generated handle, retrieve and remove from the handle map.
            if (handleMap.Remove(value, out var obj)) {
                return obj;
            } else {
                throw new InternalException($"No callback in handlemap '{value}'");
            }
        }
    }

    public override ForeignAuthenticator Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(ForeignAuthenticator value) {
        return 8;
    }

    public override void Write(ForeignAuthenticator value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
}



