    static FfiConverterTypeForeignStore() {
        UniffiCallbackInterfaceForeignStore.Register();
    }

    public override ulong Lower(ForeignStore value) {
        if (value is ForeignStoreImpl rustObj) {
            // Rust-implemented object. Clone the handle and return it.
            return rustObj.CallWithPointer(thisPtr => thisPtr);
        } else {
            // C# object, generate a new handle map entry and return it.
            return handleMap.Insert(value);
        }
    }

    public override ForeignStore Lift(ulong value) {
        if ((value & 1UL) == 0UL) {
            // Rust-generated handle, construct a new wrapper.
            return new ForeignStoreImpl(value);
        } else {
            // C#-generated handle, retrieve and remove from the handle map.
            if (handleMap.Remove(value, out var obj)) {
                return obj;
            } else {
                throw new InternalException($"No callback in handlemap '{value}'");
            }
        }
    }

    public override ForeignStore Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(ForeignStore value) {
        return 8;
    }

    public override void Write(ForeignStore value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
}



