class FfiConverterTypeVault: FfiConverter<Vault, ulong> {
    public static FfiConverterTypeVault INSTANCE = new FfiConverterTypeVault();


    public override ulong Lower(Vault value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override Vault Lift(ulong value) {
        return new Vault(value);
    }

    public override Vault Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(Vault value) {
        return 8;
    }

    public override void Write(Vault value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
}



