class FfiConverterTypeWallet: FfiConverter<Wallet, ulong> {
    public static FfiConverterTypeWallet INSTANCE = new FfiConverterTypeWallet();


    public override ulong Lower(Wallet value) {
        return value.CallWithPointer(thisPtr => thisPtr);
    }

    public override Wallet Lift(ulong value) {
        return new Wallet(value);
    }

    public override Wallet Read(BigEndianStream stream) {
        return Lift(stream.ReadULong());
    }

    public override int AllocationSize(Wallet value) {
        return 8;
    }

    public override void Write(Wallet value, BigEndianStream stream) {
        stream.WriteULong(Lower(value));
    }
}



/// <summary>
/// `accept_membership` (CTR-UA-37): slot `slot` of the `msig` `ua` accepts on `chain`, sent by `payer`.
/// </summary>
internal record AcceptMembership (
    string Chain, 
    string Ua, 
    MsigSlot Slot, 
    KeyRef Payer
) {
}

class FfiConverterTypeAcceptMembership: FfiConverterRustBuffer<AcceptMembership> {
    public static FfiConverterTypeAcceptMembership INSTANCE = new FfiConverterTypeAcceptMembership();

    public override AcceptMembership Read(BigEndianStream stream) {
        return new AcceptMembership(
            Chain: FfiConverterString.INSTANCE.Read(stream),
            Ua: FfiConverterString.INSTANCE.Read(stream),
            Slot: FfiConverterTypeMsigSlot.INSTANCE.Read(stream),
            Payer: FfiConverterTypeKeyRef.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(AcceptMembership value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.Chain)
            + FfiConverterString.INSTANCE.AllocationSize(value.Ua)
            + FfiConverterTypeMsigSlot.INSTANCE.AllocationSize(value.Slot)
            + FfiConverterTypeKeyRef.INSTANCE.AllocationSize(value.Payer);
    }

    public override void Write(AcceptMembership value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.Chain, stream);
            FfiConverterString.INSTANCE.Write(value.Ua, stream);
            FfiConverterTypeMsigSlot.INSTANCE.Write(value.Slot, stream);
            FfiConverterTypeKeyRef.INSTANCE.Write(value.Payer, stream);
    }
}



/// <summary>
/// One account row as the app shows it.
/// </summary>
/// <param name="Seed">
/// The seed the row belongs to (R2).
/// </param>
/// <param name="Shape">
/// `ua`, `native`, `key` or `watch`.
/// </param>
/// <param name="IdText">
/// A UA row's or a key row's UA, a native row's address, a watch row's id.
/// </param>
/// <param name="Verified">
/// The seed is unlocked and its index MAC verified at unlock (spec §6.2); a locked seed's rows are unverified.
/// </param>
/// <param name="Delegated">
/// An EVM row whose code is an EIP-7702 designator (`0xef0100…`), from [`Account::marks`]; the SDK builds no type-4
/// transaction, so it cannot offer to clear it (CLI-SDK-31).
/// </param>
internal record AccountInfo (
    string Id, 
    /// <summary>
    /// The seed the row belongs to (R2).
    /// </summary>
    string Seed, 
    string Name, 
    /// <summary>
    /// `ua`, `native`, `key` or `watch`.
    /// </summary>
    string Shape, 
    ushort? Kind, 
    uint? Account, 
    uint? Index, 
    string? Network, 
    /// <summary>
    /// A UA row's or a key row's UA, a native row's address, a watch row's id.
    /// </summary>
    string IdText, 
    /// <summary>
    /// The seed is unlocked and its index MAC verified at unlock (spec §6.2); a locked seed's rows are unverified.
    /// </summary>
    bool Verified, 
    /// <summary>
    /// An EVM row whose code is an EIP-7702 designator (`0xef0100…`), from [`Account::marks`]; the SDK builds no type-4
    /// transaction, so it cannot offer to clear it (CLI-SDK-31).
    /// </summary>
    bool Delegated
) {
}

class FfiConverterTypeAccountInfo: FfiConverterRustBuffer<AccountInfo> {
    public static FfiConverterTypeAccountInfo INSTANCE = new FfiConverterTypeAccountInfo();

    public override AccountInfo Read(BigEndianStream stream) {
        return new AccountInfo(
            Id: FfiConverterString.INSTANCE.Read(stream),
            Seed: FfiConverterString.INSTANCE.Read(stream),
            Name: FfiConverterString.INSTANCE.Read(stream),
            Shape: FfiConverterString.INSTANCE.Read(stream),
            Kind: FfiConverterOptionalUInt16.INSTANCE.Read(stream),
            Account: FfiConverterOptionalUInt32.INSTANCE.Read(stream),
            Index: FfiConverterOptionalUInt32.INSTANCE.Read(stream),
            Network: FfiConverterOptionalString.INSTANCE.Read(stream),
            IdText: FfiConverterString.INSTANCE.Read(stream),
            Verified: FfiConverterBoolean.INSTANCE.Read(stream),
            Delegated: FfiConverterBoolean.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(AccountInfo value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.Id)
            + FfiConverterString.INSTANCE.AllocationSize(value.Seed)
            + FfiConverterString.INSTANCE.AllocationSize(value.Name)
            + FfiConverterString.INSTANCE.AllocationSize(value.Shape)
            + FfiConverterOptionalUInt16.INSTANCE.AllocationSize(value.Kind)
            + FfiConverterOptionalUInt32.INSTANCE.AllocationSize(value.Account)
            + FfiConverterOptionalUInt32.INSTANCE.AllocationSize(value.Index)
            + FfiConverterOptionalString.INSTANCE.AllocationSize(value.Network)
            + FfiConverterString.INSTANCE.AllocationSize(value.IdText)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.Verified)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.Delegated);
    }

    public override void Write(AccountInfo value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.Id, stream);
            FfiConverterString.INSTANCE.Write(value.Seed, stream);
            FfiConverterString.INSTANCE.Write(value.Name, stream);
            FfiConverterString.INSTANCE.Write(value.Shape, stream);
            FfiConverterOptionalUInt16.INSTANCE.Write(value.Kind, stream);
            FfiConverterOptionalUInt32.INSTANCE.Write(value.Account, stream);
            FfiConverterOptionalUInt32.INSTANCE.Write(value.Index, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.Network, stream);
            FfiConverterString.INSTANCE.Write(value.IdText, stream);
            FfiConverterBoolean.INSTANCE.Write(value.Verified, stream);
            FfiConverterBoolean.INSTANCE.Write(value.Delegated, stream);
    }
}



