            + FfiConverterString.INSTANCE.AllocationSize(value.Batch)
            + FfiConverterTypeEnvelope.INSTANCE.AllocationSize(value.Envelope);
    }

    public override void Write(Execute value, BigEndianStream stream) {
            FfiConverterTypeKeyRef.INSTANCE.Write(value.Signer, stream);
            FfiConverterString.INSTANCE.Write(value.Chain, stream);
            FfiConverterString.INSTANCE.Write(value.Wallet, stream);
            FfiConverterTypeExecuteCall.INSTANCE.Write(value.Call, stream);
            FfiConverterString.INSTANCE.Write(value.Batch, stream);
            FfiConverterTypeEnvelope.INSTANCE.Write(value.Envelope, stream);
    }
}



/// <summary>
/// A base row (gas table v2, owner 2026-11-19): the execution gas of `entry` (`mtxCancelNonce`, `mtxExecuteTransfer`, …) on a
/// contract of domain kind `kind` (`token`, `zether`, `pqz`, `wallet`, `account`, `dex`, `gov_router`), on a lane whose nonce
/// is 0 (`fresh`) or above, signed by the reference signer, a native EVM key (its path makes no registry call).
/// </summary>
/// <param name="PerByte">
/// the part that grows with an input's length (owner 2026-11-19, ruling B)
/// </param>
/// <param name="Save">
/// the fixed gas added when the operation saves its `PayMeta` record (owner 2026-11-19, ruling 1)
/// </param>
/// <param name="FeeExtra">
/// the gas added when the operation's fee is > 0, measured paying a recipient holding nothing (owner 2026-11-19, ruling 3)
/// </param>
/// <param name="UaExtra">
/// the regular gas a derived-UA signer adds on this entry over the native reference signer, beyond its verify row (owner
/// 2026-11-19, A1: a derived id's ledger debit); added when the signer is a derived UA. `None`: nothing added
/// </param>
/// <param name="PerItem">
/// the part that grows with a count the operation names (owner 2026-11-19, I1); `None`: no count, nothing added
/// </param>
/// <param name="Regular">
/// the row's regular gas, its figure's part EIP-7825's per-transaction cap holds under EIP-8037 (controller call, owner
/// auto-run 2026-11-19; at a count of 0 on a counted row, whose `per_item` then carries its slope); `None`: the whole
/// figure is held to the cap
/// </param>
internal record GasBase (
    string Entry, 
    string Kind, 
    bool Fresh, 
    ulong Gas, 
    /// <summary>
    /// the part that grows with an input's length (owner 2026-11-19, ruling B)
    /// </summary>
    GasPerByte? PerByte, 
    /// <summary>
    /// the fixed gas added when the operation saves its `PayMeta` record (owner 2026-11-19, ruling 1)
    /// </summary>
    ulong? Save, 
    /// <summary>
    /// the gas added when the operation's fee is > 0, measured paying a recipient holding nothing (owner 2026-11-19, ruling 3)
    /// </summary>
    ulong? FeeExtra, 
    /// <summary>
    /// the regular gas a derived-UA signer adds on this entry over the native reference signer, beyond its verify row (owner
    /// 2026-11-19, A1: a derived id's ledger debit); added when the signer is a derived UA. `None`: nothing added
    /// </summary>
    ulong? UaExtra, 
    /// <summary>
    /// the part that grows with a count the operation names (owner 2026-11-19, I1); `None`: no count, nothing added
    /// </summary>
    GasPerItem? PerItem, 
    /// <summary>
    /// the row's regular gas, its figure's part EIP-7825's per-transaction cap holds under EIP-8037 (controller call, owner
    /// auto-run 2026-11-19; at a count of 0 on a counted row, whose `per_item` then carries its slope); `None`: the whole
    /// figure is held to the cap
    /// </summary>
    ulong? Regular
) {
}

class FfiConverterTypeGasBase: FfiConverterRustBuffer<GasBase> {
    public static FfiConverterTypeGasBase INSTANCE = new FfiConverterTypeGasBase();

    public override GasBase Read(BigEndianStream stream) {
        return new GasBase(
            Entry: FfiConverterString.INSTANCE.Read(stream),
            Kind: FfiConverterString.INSTANCE.Read(stream),
            Fresh: FfiConverterBoolean.INSTANCE.Read(stream),
            Gas: FfiConverterUInt64.INSTANCE.Read(stream),
            PerByte: FfiConverterOptionalTypeGasPerByte.INSTANCE.Read(stream),
            Save: FfiConverterOptionalUInt64.INSTANCE.Read(stream),
            FeeExtra: FfiConverterOptionalUInt64.INSTANCE.Read(stream),
            UaExtra: FfiConverterOptionalUInt64.INSTANCE.Read(stream),
            PerItem: FfiConverterOptionalTypeGasPerItem.INSTANCE.Read(stream),
            Regular: FfiConverterOptionalUInt64.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(GasBase value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.Entry)
            + FfiConverterString.INSTANCE.AllocationSize(value.Kind)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.Fresh)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.Gas)
            + FfiConverterOptionalTypeGasPerByte.INSTANCE.AllocationSize(value.PerByte)
            + FfiConverterOptionalUInt64.INSTANCE.AllocationSize(value.Save)
            + FfiConverterOptionalUInt64.INSTANCE.AllocationSize(value.FeeExtra)
            + FfiConverterOptionalUInt64.INSTANCE.AllocationSize(value.UaExtra)
            + FfiConverterOptionalTypeGasPerItem.INSTANCE.AllocationSize(value.PerItem)
            + FfiConverterOptionalUInt64.INSTANCE.AllocationSize(value.Regular);
    }

    public override void Write(GasBase value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.Entry, stream);
            FfiConverterString.INSTANCE.Write(value.Kind, stream);
            FfiConverterBoolean.INSTANCE.Write(value.Fresh, stream);
            FfiConverterUInt64.INSTANCE.Write(value.Gas, stream);
            FfiConverterOptionalTypeGasPerByte.INSTANCE.Write(value.PerByte, stream);
            FfiConverterOptionalUInt64.INSTANCE.Write(value.Save, stream);
            FfiConverterOptionalUInt64.INSTANCE.Write(value.FeeExtra, stream);
            FfiConverterOptionalUInt64.INSTANCE.Write(value.UaExtra, stream);
            FfiConverterOptionalTypeGasPerItem.INSTANCE.Write(value.PerItem, stream);
            FfiConverterOptionalUInt64.INSTANCE.Write(value.Regular, stream);
    }
}



/// <summary>
/// A verify row's registry-line columns (spec 2026-11-19-registry-verify-only-kinds §12, CTR-UA-65; §13 Gas): the row is
/// keyed by chain (the table it is in), registry address and signer kind; the verify path, the depth and the write path are
/// columns. Within one table no two verify rows share signer, registry, path, depth and write.
/// </summary>
/// <param name="Registry">
/// the registry the row was measured through (`0x` + 40 hex): a quote bound to it takes it first; `None`: a row of no one
/// registry
/// </param>
/// <param name="Path">
/// `cache`, `precompile` or `fallback` (the holder's verdict after the verify-only verifier gave no answer, §5); `None`:
/// the holder's own check
/// </param>
/// <param name="Depth">
/// the generations between the registry asked and the holder (0: the registry holds the record), at most 15
/// </param>
/// <param name="Write">
/// the write path of W1 (a registry write whose signature the holder checks), never a consumer operation's quote
/// </param>
internal record GasLine (
    /// <summary>
    /// the registry the row was measured through (`0x` + 40 hex): a quote bound to it takes it first; `None`: a row of no one
    /// registry
    /// </summary>
    string? Registry, 
    /// <summary>
    /// `cache`, `precompile` or `fallback` (the holder's verdict after the verify-only verifier gave no answer, §5); `None`:
    /// the holder's own check
    /// </summary>
    string? Path, 
    /// <summary>
    /// the generations between the registry asked and the holder (0: the registry holds the record), at most 15
    /// </summary>
    byte Depth, 
    /// <summary>
    /// the write path of W1 (a registry write whose signature the holder checks), never a consumer operation's quote
    /// </summary>
    bool Write
) {
}

class FfiConverterTypeGasLine: FfiConverterRustBuffer<GasLine> {
    public static FfiConverterTypeGasLine INSTANCE = new FfiConverterTypeGasLine();

    public override GasLine Read(BigEndianStream stream) {
        return new GasLine(
            Registry: FfiConverterOptionalString.INSTANCE.Read(stream),
            Path: FfiConverterOptionalString.INSTANCE.Read(stream),
            Depth: FfiConverterUInt8.INSTANCE.Read(stream),
            Write: FfiConverterBoolean.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(GasLine value) {
        return 0
            + FfiConverterOptionalString.INSTANCE.AllocationSize(value.Registry)
            + FfiConverterOptionalString.INSTANCE.AllocationSize(value.Path)
            + FfiConverterUInt8.INSTANCE.AllocationSize(value.Depth)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.Write);
    }

    public override void Write(GasLine value, BigEndianStream stream) {
            FfiConverterOptionalString.INSTANCE.Write(value.Registry, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.Path, stream);
            FfiConverterUInt8.INSTANCE.Write(value.Depth, stream);
            FfiConverterBoolean.INSTANCE.Write(value.Write, stream);
    }
}



/// <summary>
/// A base row's per-byte part (owner 2026-11-19, ruling B): `gas` (whole gas, rounded up) for each byte of the operation's
/// variable-length `input`: `meta.body` (a pay entry's `PayMeta` body, as encoded) or `data` (`mtxExecute`'s call data).
/// </summary>
internal record GasPerByte (
    string Input, 
    ulong Gas
) {
}

class FfiConverterTypeGasPerByte: FfiConverterRustBuffer<GasPerByte> {
