/// <summary>
/// A gas table file (spec §13.3, the gas table format): `{format: "scaas.gas-table", v: 2, name, family, assumptions, base,
/// verify}`, each base row `{entry, kind, fresh, gas, measured, source, calldata_gas?, per_byte?: {input, gas, source},
/// save?: {gas, measured, source}, fee_extra?: {gas, measured, source}, ua_extra?: {gas, measured, source}, item?,
/// per_item?: {gas, base_count, source, regular?}, stand_in?, regular?: {gas, measured, source}}`, each verify row
/// `{signer, gas, measured, source, sig_bytes, margin?, item?, per_item?, stand_in?, registry?, path?, depth?, write?}` (the
/// line's columns, [`GasLine`]), read by [`GasTable::parse`]. One format for the chain's measured rows, a module's table
/// and the SDK's reference table.
/// </summary>
/// <param name="Name">
/// a module's name, `reference`, or the chain key of a chain's measured rows
/// </param>
/// <param name="Family">
/// `evm` (the only family with a table today)
/// </param>
internal record GasTable (
    /// <summary>
    /// a module's name, `reference`, or the chain key of a chain's measured rows
    /// </summary>
    string Name, 
    /// <summary>
    /// `evm` (the only family with a table today)
    /// </summary>
    string Family, 
    GasRows Rows
) {
}

class FfiConverterTypeGasTable: FfiConverterRustBuffer<GasTable> {
    public static FfiConverterTypeGasTable INSTANCE = new FfiConverterTypeGasTable();

    public override GasTable Read(BigEndianStream stream) {
        return new GasTable(
            Name: FfiConverterString.INSTANCE.Read(stream),
            Family: FfiConverterString.INSTANCE.Read(stream),
            Rows: FfiConverterTypeGasRows.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(GasTable value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.Name)
            + FfiConverterString.INSTANCE.AllocationSize(value.Family)
            + FfiConverterTypeGasRows.INSTANCE.AllocationSize(value.Rows);
    }

    public override void Write(GasTable value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.Name, stream);
            FfiConverterString.INSTANCE.Write(value.Family, stream);
            FfiConverterTypeGasRows.INSTANCE.Write(value.Rows, stream);
    }
}



/// <summary>
/// A verify row (gas table v2): what a signer of UA kind `signer` (`0`: a native EVM key, the reference) adds over the
/// reference signer's execution gas.
/// </summary>
/// <param name="SigBytes">
/// the signer kind's signature length in calldata, `UASig` key data and signature ABI-padded (owner 2026-11-19, ruling
/// 2; for an `msig`, per member); the quote adds 64 gas a byte of it. Required in every row (owner 2026-11-19, A4); a
/// variable-length kind's longest (A5)
/// </param>
/// <param name="Margin">
/// a safety margin added to the row's gas, where the kind's worst case cannot be determined and the row is the most
/// expensive of many measurements (owner 2026-11-19, the sampled check's ruling 2 (b)); 0 when absent
/// </param>
/// <param name="PerItem">
/// the part that grows with a count of the signer's (owner 2026-11-19, I1: `members`, a `0x0121` UA's n); `None`: none
/// </param>
/// <param name="Line">
/// the registry line's columns (spec 2026-11-19-registry-verify-only-kinds §12, CTR-UA-65); all absent: the holder's own
/// check on any registry (every row before the line)
/// </param>
internal record GasVerify (
    ushort Signer, 
    ulong Gas, 
    /// <summary>
    /// the signer kind's signature length in calldata, `UASig` key data and signature ABI-padded (owner 2026-11-19, ruling
    /// 2; for an `msig`, per member); the quote adds 64 gas a byte of it. Required in every row (owner 2026-11-19, A4); a
    /// variable-length kind's longest (A5)
    /// </summary>
    ulong SigBytes, 
    /// <summary>
    /// a safety margin added to the row's gas, where the kind's worst case cannot be determined and the row is the most
    /// expensive of many measurements (owner 2026-11-19, the sampled check's ruling 2 (b)); 0 when absent
    /// </summary>
    ulong Margin, 
    /// <summary>
    /// the part that grows with a count of the signer's (owner 2026-11-19, I1: `members`, a `0x0121` UA's n); `None`: none
    /// </summary>
    GasPerItem? PerItem, 
    /// <summary>
    /// the registry line's columns (spec 2026-11-19-registry-verify-only-kinds §12, CTR-UA-65); all absent: the holder's own
    /// check on any registry (every row before the line)
    /// </summary>
    GasLine Line
) {
}

class FfiConverterTypeGasVerify: FfiConverterRustBuffer<GasVerify> {
    public static FfiConverterTypeGasVerify INSTANCE = new FfiConverterTypeGasVerify();

    public override GasVerify Read(BigEndianStream stream) {
        return new GasVerify(
            Signer: FfiConverterUInt16.INSTANCE.Read(stream),
            Gas: FfiConverterUInt64.INSTANCE.Read(stream),
            SigBytes: FfiConverterUInt64.INSTANCE.Read(stream),
            Margin: FfiConverterUInt64.INSTANCE.Read(stream),
            PerItem: FfiConverterOptionalTypeGasPerItem.INSTANCE.Read(stream),
            Line: FfiConverterTypeGasLine.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(GasVerify value) {
        return 0
            + FfiConverterUInt16.INSTANCE.AllocationSize(value.Signer)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.Gas)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.SigBytes)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.Margin)
            + FfiConverterOptionalTypeGasPerItem.INSTANCE.AllocationSize(value.PerItem)
            + FfiConverterTypeGasLine.INSTANCE.AllocationSize(value.Line);
    }

    public override void Write(GasVerify value, BigEndianStream stream) {
            FfiConverterUInt16.INSTANCE.Write(value.Signer, stream);
            FfiConverterUInt64.INSTANCE.Write(value.Gas, stream);
            FfiConverterUInt64.INSTANCE.Write(value.SigBytes, stream);
            FfiConverterUInt64.INSTANCE.Write(value.Margin, stream);
            FfiConverterOptionalTypeGasPerItem.INSTANCE.Write(value.PerItem, stream);
            FfiConverterTypeGasLine.INSTANCE.Write(value.Line, stream);
    }
}



