/// <summary>
/// A page of history.
/// </summary>
/// <param name="Ops">
/// on the first page (`before` none) only
/// </param>
/// <param name="Next">
/// where the next page starts; `None` after block 0
/// </param>
internal record HistoryPage (
    HistoryItem[] Items, 
    /// <summary>
    /// on the first page (`before` none) only
    /// </summary>
    OpItem[] Ops, 
    /// <summary>
    /// where the next page starts; `None` after block 0
    /// </summary>
    Cursor? Next
) {
}

class FfiConverterTypeHistoryPage: FfiConverterRustBuffer<HistoryPage> {
    public static FfiConverterTypeHistoryPage INSTANCE = new FfiConverterTypeHistoryPage();

    public override HistoryPage Read(BigEndianStream stream) {
        return new HistoryPage(
            Items: FfiConverterSequenceTypeHistoryItem.INSTANCE.Read(stream),
            Ops: FfiConverterSequenceTypeOpItem.INSTANCE.Read(stream),
            Next: FfiConverterOptionalTypeCursor.INSTANCE.Read(stream)
        );
