/// <summary>
/// The SDK's caps and queues (spec §4). The fee caps are the app's to set for its chains; the defaults below are a floor
/// against a runaway quote, never a value assumed of a chain.
/// </summary>
/// <param name="MaxFeePerGas">
/// decimal wei
/// </param>
/// <param name="MaxCost">
/// decimal wei
/// </param>
/// <param name="MaxWatch">
/// accounts × chains × tokens per poll
/// </param>
/// <param name="MaxConcurrentHeavy">
/// scrypt, Argon2id, proofs, slow key generation at once
/// </param>
/// <param name="MaxValidSecs">
/// the longest an operation's `validUntil` may lie ahead of the SDK's clock, in seconds (the signing check's window), where
/// a profile names none
/// </param>
/// <param name="StateRetentionSecs">
/// how long a terminal operation row stays in `sdk.state` after it ended, in seconds (default 90 days); a non-terminal row
/// is never pruned (owner 2026-11-19, T13b ruling 2)
/// </param>
/// <param name="MaxNativeCost">
/// the most a family's native transaction may cost its payer, per chain profile, as a decimal string in the chain's
/// smallest unit (spec §27.5 (e): fee + storage + forward; plan T41): never from an endpoint. A chain without its row
/// spends nothing natively (`FeeAboveCap`: fail closed). EVM's self-relay keeps `max_cost`
/// </param>
internal record Limits (
    /// <summary>
    /// decimal wei
    /// </summary>
    string MaxFeePerGas, 
    ulong MaxGas, 
    /// <summary>
    /// decimal wei
    /// </summary>
    string MaxCost, 
    ulong WatchPollMs, 
    /// <summary>
    /// accounts × chains × tokens per poll
    /// </summary>
    uint MaxWatch, 
    /// <summary>
    /// scrypt, Argon2id, proofs, slow key generation at once
    /// </summary>
    uint MaxConcurrentHeavy, 
    /// <summary>
    /// the longest an operation's `validUntil` may lie ahead of the SDK's clock, in seconds (the signing check's window), where
    /// a profile names none
    /// </summary>
    ulong MaxValidSecs, 
    uint EventQueue, 
    /// <summary>
    /// how long a terminal operation row stays in `sdk.state` after it ended, in seconds (default 90 days); a non-terminal row
    /// is never pruned (owner 2026-11-19, T13b ruling 2)
    /// </summary>
    ulong StateRetentionSecs, 
    /// <summary>
    /// the most a family's native transaction may cost its payer, per chain profile, as a decimal string in the chain's
    /// smallest unit (spec §27.5 (e): fee + storage + forward; plan T41): never from an endpoint. A chain without its row
    /// spends nothing natively (`FeeAboveCap`: fail closed). EVM's self-relay keeps `max_cost`
    /// </summary>
    NativeCap[] MaxNativeCost
) {
}

class FfiConverterTypeLimits: FfiConverterRustBuffer<Limits> {
    public static FfiConverterTypeLimits INSTANCE = new FfiConverterTypeLimits();

    public override Limits Read(BigEndianStream stream) {
        return new Limits(
            MaxFeePerGas: FfiConverterString.INSTANCE.Read(stream),
            MaxGas: FfiConverterUInt64.INSTANCE.Read(stream),
            MaxCost: FfiConverterString.INSTANCE.Read(stream),
            WatchPollMs: FfiConverterUInt64.INSTANCE.Read(stream),
            MaxWatch: FfiConverterUInt32.INSTANCE.Read(stream),
            MaxConcurrentHeavy: FfiConverterUInt32.INSTANCE.Read(stream),
            MaxValidSecs: FfiConverterUInt64.INSTANCE.Read(stream),
            EventQueue: FfiConverterUInt32.INSTANCE.Read(stream),
            StateRetentionSecs: FfiConverterUInt64.INSTANCE.Read(stream),
            MaxNativeCost: FfiConverterSequenceTypeNativeCap.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(Limits value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.MaxFeePerGas)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.MaxGas)
            + FfiConverterString.INSTANCE.AllocationSize(value.MaxCost)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.WatchPollMs)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.MaxWatch)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.MaxConcurrentHeavy)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.MaxValidSecs)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.EventQueue)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.StateRetentionSecs)
            + FfiConverterSequenceTypeNativeCap.INSTANCE.AllocationSize(value.MaxNativeCost);
    }

    public override void Write(Limits value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.MaxFeePerGas, stream);
            FfiConverterUInt64.INSTANCE.Write(value.MaxGas, stream);
            FfiConverterString.INSTANCE.Write(value.MaxCost, stream);
            FfiConverterUInt64.INSTANCE.Write(value.WatchPollMs, stream);
            FfiConverterUInt32.INSTANCE.Write(value.MaxWatch, stream);
            FfiConverterUInt32.INSTANCE.Write(value.MaxConcurrentHeavy, stream);
            FfiConverterUInt64.INSTANCE.Write(value.MaxValidSecs, stream);
            FfiConverterUInt32.INSTANCE.Write(value.EventQueue, stream);
            FfiConverterUInt64.INSTANCE.Write(value.StateRetentionSecs, stream);
            FfiConverterSequenceTypeNativeCap.INSTANCE.Write(value.MaxNativeCost, stream);
    }
}



/// <summary>
/// A liquidity order (`LiquidityOrder`, CTR-DEX-30; dex-liquidity spec §4.2), signed in its DEX's domain.
/// </summary>
/// <param name="Dex">
/// a DEX of the profile's list with its liquidity mark
/// </param>
/// <param name="PositionPool">
/// `0x` + 64 hex; `None`: no position received
/// </param>
/// <param name="Recipient">
/// a 32-byte id; `None`: the signer
/// </param>
/// <param name="Nonce">
/// the order's nonce (the planner's; no lane is read)
/// </param>
/// <param name="ExtraTokens">
/// tokens the plan counts beside its inputs and outputs (at most eight)
/// </param>
/// <param name="Partial">
/// a partial withdraw or fee collect (it must receive the position back)
/// </param>
internal record LiquidityOrder (
    KeyRef Signer, 
    string Chain, 
    /// <summary>
    /// a DEX of the profile's list with its liquidity mark
    /// </summary>
    string Dex, 
    LiquidityToken[] Inputs, 
    LiquidityToken[] Outputs, 
    string? PositionManager, 
    string? PositionReader, 
    string PositionIn, 
    /// <summary>
    /// `0x` + 64 hex; `None`: no position received
    /// </summary>
    string? PositionPool, 
    int TickLower, 
    int TickUpper, 
    string MinLiquidity, 
    /// <summary>
    /// a 32-byte id; `None`: the signer
    /// </summary>
    string? Recipient, 
    string Fee, 
    string Relayer, 
    byte Flags, 
    string Batch, 
    /// <summary>
    /// the order's nonce (the planner's; no lane is read)
    /// </summary>
    string Nonce, 
    ulong ValidUntil, 
    /// <summary>
    /// tokens the plan counts beside its inputs and outputs (at most eight)
    /// </summary>
    string[] ExtraTokens, 
    /// <summary>
    /// a partial withdraw or fee collect (it must receive the position back)
    /// </summary>
    bool Partial
) {
}

class FfiConverterTypeLiquidityOrder: FfiConverterRustBuffer<LiquidityOrder> {
    public static FfiConverterTypeLiquidityOrder INSTANCE = new FfiConverterTypeLiquidityOrder();

    public override LiquidityOrder Read(BigEndianStream stream) {
        return new LiquidityOrder(
            Signer: FfiConverterTypeKeyRef.INSTANCE.Read(stream),
            Chain: FfiConverterString.INSTANCE.Read(stream),
            Dex: FfiConverterString.INSTANCE.Read(stream),
            Inputs: FfiConverterSequenceTypeLiquidityToken.INSTANCE.Read(stream),
            Outputs: FfiConverterSequenceTypeLiquidityToken.INSTANCE.Read(stream),
            PositionManager: FfiConverterOptionalString.INSTANCE.Read(stream),
            PositionReader: FfiConverterOptionalString.INSTANCE.Read(stream),
            PositionIn: FfiConverterString.INSTANCE.Read(stream),
            PositionPool: FfiConverterOptionalString.INSTANCE.Read(stream),
            TickLower: FfiConverterInt32.INSTANCE.Read(stream),
            TickUpper: FfiConverterInt32.INSTANCE.Read(stream),
            MinLiquidity: FfiConverterString.INSTANCE.Read(stream),
            Recipient: FfiConverterOptionalString.INSTANCE.Read(stream),
            Fee: FfiConverterString.INSTANCE.Read(stream),
            Relayer: FfiConverterString.INSTANCE.Read(stream),
            Flags: FfiConverterUInt8.INSTANCE.Read(stream),
            Batch: FfiConverterString.INSTANCE.Read(stream),
            Nonce: FfiConverterString.INSTANCE.Read(stream),
            ValidUntil: FfiConverterUInt64.INSTANCE.Read(stream),
            ExtraTokens: FfiConverterSequenceString.INSTANCE.Read(stream),
            Partial: FfiConverterBoolean.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(LiquidityOrder value) {
        return 0
            + FfiConverterTypeKeyRef.INSTANCE.AllocationSize(value.Signer)
            + FfiConverterString.INSTANCE.AllocationSize(value.Chain)
            + FfiConverterString.INSTANCE.AllocationSize(value.Dex)
            + FfiConverterSequenceTypeLiquidityToken.INSTANCE.AllocationSize(value.Inputs)
            + FfiConverterSequenceTypeLiquidityToken.INSTANCE.AllocationSize(value.Outputs)
            + FfiConverterOptionalString.INSTANCE.AllocationSize(value.PositionManager)
            + FfiConverterOptionalString.INSTANCE.AllocationSize(value.PositionReader)
            + FfiConverterString.INSTANCE.AllocationSize(value.PositionIn)
            + FfiConverterOptionalString.INSTANCE.AllocationSize(value.PositionPool)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.TickLower)
            + FfiConverterInt32.INSTANCE.AllocationSize(value.TickUpper)
            + FfiConverterString.INSTANCE.AllocationSize(value.MinLiquidity)
            + FfiConverterOptionalString.INSTANCE.AllocationSize(value.Recipient)
            + FfiConverterString.INSTANCE.AllocationSize(value.Fee)
            + FfiConverterString.INSTANCE.AllocationSize(value.Relayer)
            + FfiConverterUInt8.INSTANCE.AllocationSize(value.Flags)
            + FfiConverterString.INSTANCE.AllocationSize(value.Batch)
            + FfiConverterString.INSTANCE.AllocationSize(value.Nonce)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.ValidUntil)
            + FfiConverterSequenceString.INSTANCE.AllocationSize(value.ExtraTokens)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.Partial);
    }

    public override void Write(LiquidityOrder value, BigEndianStream stream) {
            FfiConverterTypeKeyRef.INSTANCE.Write(value.Signer, stream);
            FfiConverterString.INSTANCE.Write(value.Chain, stream);
            FfiConverterString.INSTANCE.Write(value.Dex, stream);
            FfiConverterSequenceTypeLiquidityToken.INSTANCE.Write(value.Inputs, stream);
            FfiConverterSequenceTypeLiquidityToken.INSTANCE.Write(value.Outputs, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.PositionManager, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.PositionReader, stream);
            FfiConverterString.INSTANCE.Write(value.PositionIn, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.PositionPool, stream);
            FfiConverterInt32.INSTANCE.Write(value.TickLower, stream);
            FfiConverterInt32.INSTANCE.Write(value.TickUpper, stream);
            FfiConverterString.INSTANCE.Write(value.MinLiquidity, stream);
            FfiConverterOptionalString.INSTANCE.Write(value.Recipient, stream);
            FfiConverterString.INSTANCE.Write(value.Fee, stream);
            FfiConverterString.INSTANCE.Write(value.Relayer, stream);
            FfiConverterUInt8.INSTANCE.Write(value.Flags, stream);
            FfiConverterString.INSTANCE.Write(value.Batch, stream);
            FfiConverterString.INSTANCE.Write(value.Nonce, stream);
            FfiConverterUInt64.INSTANCE.Write(value.ValidUntil, stream);
            FfiConverterSequenceString.INSTANCE.Write(value.ExtraTokens, stream);
            FfiConverterBoolean.INSTANCE.Write(value.Partial, stream);
    }
}



