/// <summary>
/// An `msig` on the profile's registry (`msig_state`).
/// </summary>
/// <param name="First">
/// the structure the id derives from (`registrationOf`)
/// </param>
/// <param name="Threshold">
/// the current threshold (`msigOf`)
/// </param>
/// <param name="Slots">
/// the current slots, disabled ones included
/// </param>
/// <param name="Version">
/// `msigStateOf`'s update counter (0: never updated here)
/// </param>
/// <param name="ActiveWeight">
/// the weight of the slots enabled and accepted
/// </param>
/// <param name="Active">
/// that weight reaches the threshold: until then the `msig` authorizes nothing (CTR-UA-37)
/// </param>
internal record MsigState (
    string Ua, 
    /// <summary>
    /// the structure the id derives from (`registrationOf`)
    /// </summary>
    MsigStructureArgs First, 
    /// <summary>
    /// the current threshold (`msigOf`)
    /// </summary>
    ushort Threshold, 
    /// <summary>
    /// the current slots, disabled ones included
    /// </summary>
    MsigSlotState[] Slots, 
    /// <summary>
    /// `msigStateOf`'s update counter (0: never updated here)
    /// </summary>
    ulong Version, 
    /// <summary>
    /// the weight of the slots enabled and accepted
    /// </summary>
    uint ActiveWeight, 
    /// <summary>
    /// that weight reaches the threshold: until then the `msig` authorizes nothing (CTR-UA-37)
    /// </summary>
    bool Active
) {
}

class FfiConverterTypeMsigState: FfiConverterRustBuffer<MsigState> {
    public static FfiConverterTypeMsigState INSTANCE = new FfiConverterTypeMsigState();

    public override MsigState Read(BigEndianStream stream) {
        return new MsigState(
            Ua: FfiConverterString.INSTANCE.Read(stream),
            First: FfiConverterTypeMsigStructureArgs.INSTANCE.Read(stream),
            Threshold: FfiConverterUInt16.INSTANCE.Read(stream),
            Slots: FfiConverterSequenceTypeMsigSlotState.INSTANCE.Read(stream),
            Version: FfiConverterUInt64.INSTANCE.Read(stream),
            ActiveWeight: FfiConverterUInt32.INSTANCE.Read(stream),
            Active: FfiConverterBoolean.INSTANCE.Read(stream)
        );
    }

    public override int AllocationSize(MsigState value) {
        return 0
            + FfiConverterString.INSTANCE.AllocationSize(value.Ua)
            + FfiConverterTypeMsigStructureArgs.INSTANCE.AllocationSize(value.First)
            + FfiConverterUInt16.INSTANCE.AllocationSize(value.Threshold)
            + FfiConverterSequenceTypeMsigSlotState.INSTANCE.AllocationSize(value.Slots)
            + FfiConverterUInt64.INSTANCE.AllocationSize(value.Version)
            + FfiConverterUInt32.INSTANCE.AllocationSize(value.ActiveWeight)
            + FfiConverterBoolean.INSTANCE.AllocationSize(value.Active);
    }

    public override void Write(MsigState value, BigEndianStream stream) {
            FfiConverterString.INSTANCE.Write(value.Ua, stream);
            FfiConverterTypeMsigStructureArgs.INSTANCE.Write(value.First, stream);
            FfiConverterUInt16.INSTANCE.Write(value.Threshold, stream);
            FfiConverterSequenceTypeMsigSlotState.INSTANCE.Write(value.Slots, stream);
            FfiConverterUInt64.INSTANCE.Write(value.Version, stream);
            FfiConverterUInt32.INSTANCE.Write(value.ActiveWeight, stream);
            FfiConverterBoolean.INSTANCE.Write(value.Active, stream);
    }
}



