/// <summary>
/// An account row, by shape (spec §6.1), each with its fields in the written order.
/// </summary>
internal record AccountRow {
    
    public record Ua (
        string Id,
        string Name,
        ulong Kind,
        ulong Account,
        ulong Index,
        string UaValue
    ) : AccountRow {}
    
    public record Native (
        string Id,
        string Name,
        string Network,
        ulong Index,
        ulong? CoinType,
        ulong? Change,
        string? Path,
        ulong? Ss58Prefix,
        string Address
    ) : AccountRow {}
    
    public record Key (
        string Id,
        string Name,
        ulong Kind,
        string KeyData,
        string? CredentialId,
        string? Handle,
        string UaValue
    ) : AccountRow {}
    
    public record Watch (
        string Id,
        string Name,
        string WatchValue
