/// <summary>
/// An authenticator's failure; `Unexpected` is a foreign exception inside the app's implementation.
/// </summary>
internal class AuthException: UniffiException {
    AuthException() : base() {}
    AuthException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    public class Refused : AuthException {
        public Refused() : base() {}
    }
    
    
    public class Cancelled : AuthException {
        public Cancelled() : base() {}
    }
    
    
    public class Unavailable : AuthException {
        public Unavailable() : base() {}
    }
    
    
    public class Unexpected : AuthException {
        public Unexpected() : base() {}
    }
    
    

    
}

class FfiConverterTypeAuthError : FfiConverterRustBuffer<AuthException>, CallStatusErrorHandler<AuthException> {
    public static FfiConverterTypeAuthError INSTANCE = new FfiConverterTypeAuthError();

    public override AuthException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new AuthException.Refused();
            case 2:
                return new AuthException.Cancelled();
            case 3:
                return new AuthException.Unavailable();
            case 4:
                return new AuthException.Unexpected();
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeAuthError.Read()", value));
        }
    }

    public override int AllocationSize(AuthException value) {
        switch (value) {

            case AuthException.Refused variant_value:
                return 4;

            case AuthException.Cancelled variant_value:
                return 4;

            case AuthException.Unavailable variant_value:
                return 4;

            case AuthException.Unexpected variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeAuthError.AllocationSize()", value));
        }
    }

    public override void Write(AuthException value, BigEndianStream stream) {
        switch (value) {
            case AuthException.Refused variant_value:
                stream.WriteInt(1);
                break;
            case AuthException.Cancelled variant_value:
                stream.WriteInt(2);
                break;
            case AuthException.Unavailable variant_value:
                stream.WriteInt(3);
                break;
            case AuthException.Unexpected variant_value:
                stream.WriteInt(4);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeAuthError.Write()", value));
        }
    }
}





internal enum Class: int {
    Named,
    Default,
    Discovered
}

class FfiConverterTypeClass: FfiConverterRustBuffer<Class> {
    public static FfiConverterTypeClass INSTANCE = new FfiConverterTypeClass();

    public override Class Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return Class.Named;
            case 2: return Class.Default;
            case 3: return Class.Discovered;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeClass.Read()", value));
        }
    }

    public override int AllocationSize(Class value) {
        return 4;
    }

    public override void Write(Class value, BigEndianStream stream) {
        switch (value) {
            case Class.Named: stream.WriteInt(1); break;
            case Class.Default: stream.WriteInt(2); break;
            case Class.Discovered: stream.WriteInt(3); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeClass.Write()", value));
        }
    }
}







/// <summary>
/// One delay sentence of a power bit, by name.
/// </summary>
internal record DelaySentence {
    
    /// <summary>
    /// `atOnce`: the delay is 0, a holder's change applies at once
    /// </summary>
    public record AtOnce: DelaySentence {}
    
    
    /// <summary>
    /// the change applies after `delay` seconds, the longer of the factory's notice period and the token's grant delay
    /// </summary>
    public record After (
        ulong Delay
    ) : DelaySentence {}
    
    /// <summary>
    /// `singleKey`: the holder is a single key
    /// </summary>
    public record SingleKey: DelaySentence {}
    
    
    /// <summary>
    /// `locked`: the bit is locked and the admin is gone; nobody can revoke its holders
    /// </summary>
    public record Locked: DelaySentence {}
    
    
    /// <summary>
    /// a bit of the table without delay sentences
    /// </summary>
    public record NoDelay: DelaySentence {}
    
    
    /// <summary>
    /// a bit the table does not know
    /// </summary>
    public record Unknown: DelaySentence {}
    
    

    
}

class FfiConverterTypeDelaySentence : FfiConverterRustBuffer<DelaySentence>{
