        switch (value) {
            case 1:
                return new DelaySentence.AtOnce(
                );
            case 2:
                return new DelaySentence.After(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 3:
                return new DelaySentence.SingleKey(
                );
            case 4:
                return new DelaySentence.Locked(
                );
            case 5:
                return new DelaySentence.NoDelay(
                );
            case 6:
                return new DelaySentence.Unknown(
                );
            default:
