        }
    }

    public override int AllocationSize(DelaySentence value) {
        switch (value) {
            case DelaySentence.AtOnce variant_value:
                return 4;
            case DelaySentence.After variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.Delay);
            case DelaySentence.SingleKey variant_value:
                return 4;
            case DelaySentence.Locked variant_value:
                return 4;
            case DelaySentence.NoDelay variant_value:
                return 4;
            case DelaySentence.Unknown variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeDelaySentence.AllocationSize()", value));
        }
    }

    public override void Write(DelaySentence value, BigEndianStream stream) {
        switch (value) {
            case DelaySentence.AtOnce variant_value:
                stream.WriteInt(1);
                break;
            case DelaySentence.After variant_value:
                stream.WriteInt(2);
                FfiConverterUInt64.INSTANCE.Write(variant_value.Delay, stream);
                break;
            case DelaySentence.SingleKey variant_value:
                stream.WriteInt(3);
                break;
            case DelaySentence.Locked variant_value:
                stream.WriteInt(4);
                break;
            case DelaySentence.NoDelay variant_value:
                stream.WriteInt(5);
                break;
            case DelaySentence.Unknown variant_value:
                stream.WriteInt(6);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeDelaySentence.Write()", value));
        }
    }
}







