/// <summary>
/// An SDK event (appended only).
/// </summary>
internal record Event {
    
    public record SeedUnlocked (
        string Seed
    ) : Event {}
    
    public record SeedLocked (
        string Seed
    ) : Event {}
    
    public record KeystoreChanged (
        ulong Rev
    ) : Event {}
    
    public record KeystoreMismatch (
        string Seed
    ) : Event {}
    
    public record KeystoreRollback: Event {}
    
    
    public record HiddenOpsAbandoned (
        uint Count
    ) : Event {}
    
    /// <summary>
    /// The subscriber's queue overflowed: `missed` events were dropped for it
    /// </summary>
    public record Lagged (
        ulong Missed
    ) : Event {}
    
    /// <summary>
    /// An operation's state changed (spec §13.4, §13.5): every send result after `submit` arrives here, never as its error.
    /// </summary>
    public record OpState (
        string Op,
        uniffi.scaas_sdk.OpState State
    ) : Event {}
    
    /// <summary>
    /// A watched token's balance moved at the profile's final block (spec §14).
    /// </summary>
    public record BalanceChanged (
        string Account,
        string Chain,
        string Token
    ) : Event {}
    
    /// <summary>
    /// A watched account's new history items (spec §8.4), newest first.
    /// </summary>
    public record HistoryAdded (
        string Account,
        string Chain,
        HistoryItem[] Items
    ) : Event {}
    
    /// <summary>
    /// Another process changed `sdk.state` (R17): its `rev` now.
    /// </summary>
    public record StateChanged (
        ulong Rev
    ) : Event {}
    

    
}

class FfiConverterTypeEvent : FfiConverterRustBuffer<Event>{
    public static FfiConverterRustBuffer<Event> INSTANCE = new FfiConverterTypeEvent();

    public override Event Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new Event.SeedUnlocked(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 2:
                return new Event.SeedLocked(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 3:
                return new Event.KeystoreChanged(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 4:
                return new Event.KeystoreMismatch(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 5:
                return new Event.KeystoreRollback(
                );
            case 6:
                return new Event.HiddenOpsAbandoned(
                    FfiConverterUInt32.INSTANCE.Read(stream)
                );
            case 7:
                return new Event.Lagged(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 8:
                return new Event.OpState(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterTypeOpState.INSTANCE.Read(stream)
                );
            case 9:
                return new Event.BalanceChanged(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 10:
                return new Event.HistoryAdded(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterSequenceTypeHistoryItem.INSTANCE.Read(stream)
                );
            case 11:
                return new Event.StateChanged(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeEvent.Read()", value));
        }
    }

    public override int AllocationSize(Event value) {
        switch (value) {
            case Event.SeedUnlocked variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed);
            case Event.SeedLocked variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed);
            case Event.KeystoreChanged variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.Rev);
            case Event.KeystoreMismatch variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed);
            case Event.KeystoreRollback variant_value:
                return 4;
            case Event.HiddenOpsAbandoned variant_value:
                return 4
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Count);
            case Event.Lagged variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.Missed);
            case Event.OpState variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Op)
                    + FfiConverterTypeOpState.INSTANCE.AllocationSize(variant_value.State);
            case Event.BalanceChanged variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Account)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Chain)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Token);
            case Event.HistoryAdded variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Account)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Chain)
                    + FfiConverterSequenceTypeHistoryItem.INSTANCE.AllocationSize(variant_value.Items);
            case Event.StateChanged variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.Rev);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeEvent.AllocationSize()", value));
        }
    }

    public override void Write(Event value, BigEndianStream stream) {
        switch (value) {
            case Event.SeedUnlocked variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                break;
            case Event.SeedLocked variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                break;
            case Event.KeystoreChanged variant_value:
                stream.WriteInt(3);
                FfiConverterUInt64.INSTANCE.Write(variant_value.Rev, stream);
                break;
            case Event.KeystoreMismatch variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                break;
            case Event.KeystoreRollback variant_value:
                stream.WriteInt(5);
                break;
            case Event.HiddenOpsAbandoned variant_value:
                stream.WriteInt(6);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Count, stream);
                break;
            case Event.Lagged variant_value:
                stream.WriteInt(7);
                FfiConverterUInt64.INSTANCE.Write(variant_value.Missed, stream);
                break;
            case Event.OpState variant_value:
                stream.WriteInt(8);
                FfiConverterString.INSTANCE.Write(variant_value.Op, stream);
                FfiConverterTypeOpState.INSTANCE.Write(variant_value.State, stream);
                break;
            case Event.BalanceChanged variant_value:
                stream.WriteInt(9);
                FfiConverterString.INSTANCE.Write(variant_value.Account, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Chain, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Token, stream);
                break;
            case Event.HistoryAdded variant_value:
                stream.WriteInt(10);
                FfiConverterString.INSTANCE.Write(variant_value.Account, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Chain, stream);
                FfiConverterSequenceTypeHistoryItem.INSTANCE.Write(variant_value.Items, stream);
                break;
            case Event.StateChanged variant_value:
                stream.WriteInt(11);
                FfiConverterUInt64.INSTANCE.Write(variant_value.Rev, stream);
                break;
            default:
