/// <summary>
/// A mandate wallet's call (spec §13.2): decoded, or opaque under the marker.
/// </summary>
internal record ExecuteCall {
    
    /// <summary>
    /// an ERC-20 `transfer(to, amount)` of `token` held by the wallet
    /// </summary>
    public record Transfer (
        string Token,
        string To,
        string Amount
    ) : ExecuteCall {}
    
    /// <summary>
    /// any other call: `OpaqueCallRefused` without the marker
    /// </summary>
    public record Opaque (
        string Target,
        string Value,
        string Data,
        AllowOpaqueCall? Allow
    ) : ExecuteCall {}
    

    
}

class FfiConverterTypeExecuteCall : FfiConverterRustBuffer<ExecuteCall>{
    public static FfiConverterRustBuffer<ExecuteCall> INSTANCE = new FfiConverterTypeExecuteCall();

    public override ExecuteCall Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new ExecuteCall.Transfer(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 2:
                return new ExecuteCall.Opaque(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterOptionalTypeAllowOpaqueCall.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeExecuteCall.Read()", value));
        }
    }

    public override int AllocationSize(ExecuteCall value) {
        switch (value) {
            case ExecuteCall.Transfer variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Token)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.To)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Amount);
            case ExecuteCall.Opaque variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Target)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Value)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Data)
                    + FfiConverterOptionalTypeAllowOpaqueCall.INSTANCE.AllocationSize(variant_value.Allow);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeExecuteCall.AllocationSize()", value));
        }
    }

    public override void Write(ExecuteCall value, BigEndianStream stream) {
        switch (value) {
            case ExecuteCall.Transfer variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.Token, stream);
                FfiConverterString.INSTANCE.Write(variant_value.To, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Amount, stream);
                break;
            case ExecuteCall.Opaque variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.Target, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Value, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Data, stream);
                FfiConverterOptionalTypeAllowOpaqueCall.INSTANCE.Write(variant_value.Allow, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeExecuteCall.Write()", value));
        }
    }
}







/// <summary>
/// A chain family (the `scaas-rpc` readers'). Hedera is `Evm` with its chain id.
/// </summary>
internal enum Family: int {
    Evm,
    Soroban,
    Solana,
    Near,
    Algorand,
    Aptos,
    Sui,
    Cosmos,
    Ton
}

class FfiConverterTypeFamily: FfiConverterRustBuffer<Family> {
    public static FfiConverterTypeFamily INSTANCE = new FfiConverterTypeFamily();

    public override Family Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return Family.Evm;
            case 2: return Family.Soroban;
            case 3: return Family.Solana;
            case 4: return Family.Near;
            case 5: return Family.Algorand;
            case 6: return Family.Aptos;
            case 7: return Family.Sui;
            case 8: return Family.Cosmos;
            case 9: return Family.Ton;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFamily.Read()", value));
        }
    }

    public override int AllocationSize(Family value) {
        return 4;
    }

    public override void Write(Family value, BigEndianStream stream) {
        switch (value) {
            case Family.Evm: stream.WriteInt(1); break;
            case Family.Soroban: stream.WriteInt(2); break;
            case Family.Solana: stream.WriteInt(3); break;
            case Family.Near: stream.WriteInt(4); break;
            case Family.Algorand: stream.WriteInt(5); break;
            case Family.Aptos: stream.WriteInt(6); break;
            case Family.Sui: stream.WriteInt(7); break;
            case Family.Cosmos: stream.WriteInt(8); break;
            case Family.Ton: stream.WriteInt(9); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFamily.Write()", value));
        }
    }
}







/// <summary>
/// A family's own profile data (spec §8.7 rule 2; decisions CLI-SDK-15's Changes of 2026-11-21).
/// </summary>
internal record FamilyParams {
    
    /// <summary>
    /// Cosmos: the chain id the gateways' `node_info` must name (the identity a Cosmos node answers; `chain_uid` stays the
    /// profile's 32-byte network id), the REST gateways with their policy (the profile's `rpc` are the CometBFT endpoints),
    /// the native denom and the bech32 prefix of the chain's addresses
    /// </summary>
    public record Cosmos (
        string ChainId,
        EndpointConfig[] Rest,
        Policy RestPolicy,
        string Denom,
        string Prefix
    ) : FamilyParams {}
    
    /// <summary>
    /// Aptos: the chain id ledger info must name (`aptos_framework::chain_id`, 1 to 255; the identity an Aptos node answers)
    /// and the `scaas` package's address, whose view `meta::account_of(owner)` gives the Account an owner's tokens are in
    /// (NET-APT-05), as `0x` + 64 lowercase hex (AIP-40's long form)
    /// </summary>
    public record Aptos (
        byte ChainId,
        string Package
    ) : FamilyParams {}
    
    /// <summary>
    /// Solana: the `scaas` program's id (base58 of 32 bytes), under which an owner's SCaaS Account is the `["acct", owner]`
    /// program address (`ua-rs` `families::solana`); the cluster's identity is its genesis hash, `chain_uid`'s 32 bytes
    /// </summary>
    public record Solana (
        string Program
    ) : FamilyParams {}
    
    /// <summary>
    /// Soroban: the network passphrase its RPC endpoints name (`getNetwork`; its SHA-256 is `chain_uid`, checked at `Sdk::open`)
    /// and the XLM SAC contract (`C…`), pinned, whose balance entry is a `C…` holder's native XLM (never derived here)
    /// </summary>
    public record Soroban (
        string Passphrase,
        string XlmSac
    ) : FamilyParams {}
    
    /// <summary>
    /// Sui: the GraphQL endpoints the reads go to, with their policy (public fullnodes refuse JSON-RPC, docs/networks/sui.md
    /// §14; the profile's `rpc` are the JSON-RPC endpoints), each named by `chain_uid`, the genesis checkpoint's digest, whose
    /// 32 bytes in base58 `chainIdentifier` must answer
    /// </summary>
    public record Sui (
        EndpointConfig[] Graphql,
        Policy GraphqlPolicy
    ) : FamilyParams {}
    
    /// <summary>
    /// Polkadot Hub's Substrate side on its EVM profile (decisions CLI-SDK-32's Change of 2026-11-22, plan T32's read part): the
    /// Substrate JSON-RPC endpoints with their policy, each named by `genesis` (`0x` + 64 hex, `chain_getBlockHash(0)`), and the
    /// SS58 prefix of the chain's addresses (0 to 16,383, not 46 or 47); `balances` of an SS58 id reads its `System.Account`
    /// there. The same params serve the relay chain's Substrate side
    /// </summary>
    public record Substrate (
        EndpointConfig[] Rpc,
        Policy RpcPolicy,
        string Genesis,
        ushort Ss58Prefix
    ) : FamilyParams {}
    

    
}

class FfiConverterTypeFamilyParams : FfiConverterRustBuffer<FamilyParams>{
    public static FfiConverterRustBuffer<FamilyParams> INSTANCE = new FfiConverterTypeFamilyParams();

    public override FamilyParams Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new FamilyParams.Cosmos(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterSequenceTypeEndpointConfig.INSTANCE.Read(stream),
                    FfiConverterTypePolicy.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 2:
                return new FamilyParams.Aptos(
                    FfiConverterUInt8.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 3:
                return new FamilyParams.Solana(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 4:
                return new FamilyParams.Soroban(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 5:
                return new FamilyParams.Sui(
                    FfiConverterSequenceTypeEndpointConfig.INSTANCE.Read(stream),
                    FfiConverterTypePolicy.INSTANCE.Read(stream)
                );
            case 6:
                return new FamilyParams.Substrate(
                    FfiConverterSequenceTypeEndpointConfig.INSTANCE.Read(stream),
                    FfiConverterTypePolicy.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt16.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFamilyParams.Read()", value));
        }
    }

    public override int AllocationSize(FamilyParams value) {
        switch (value) {
            case FamilyParams.Cosmos variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.ChainId)
                    + FfiConverterSequenceTypeEndpointConfig.INSTANCE.AllocationSize(variant_value.Rest)
                    + FfiConverterTypePolicy.INSTANCE.AllocationSize(variant_value.RestPolicy)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Denom)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Prefix);
            case FamilyParams.Aptos variant_value:
                return 4
                    + FfiConverterUInt8.INSTANCE.AllocationSize(variant_value.ChainId)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Package);
            case FamilyParams.Solana variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Program);
            case FamilyParams.Soroban variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Passphrase)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.XlmSac);
            case FamilyParams.Sui variant_value:
                return 4
                    + FfiConverterSequenceTypeEndpointConfig.INSTANCE.AllocationSize(variant_value.Graphql)
                    + FfiConverterTypePolicy.INSTANCE.AllocationSize(variant_value.GraphqlPolicy);
            case FamilyParams.Substrate variant_value:
                return 4
                    + FfiConverterSequenceTypeEndpointConfig.INSTANCE.AllocationSize(variant_value.Rpc)
                    + FfiConverterTypePolicy.INSTANCE.AllocationSize(variant_value.RpcPolicy)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Genesis)
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.Ss58Prefix);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFamilyParams.AllocationSize()", value));
        }
    }

    public override void Write(FamilyParams value, BigEndianStream stream) {
        switch (value) {
            case FamilyParams.Cosmos variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.ChainId, stream);
                FfiConverterSequenceTypeEndpointConfig.INSTANCE.Write(variant_value.Rest, stream);
                FfiConverterTypePolicy.INSTANCE.Write(variant_value.RestPolicy, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Denom, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Prefix, stream);
                break;
            case FamilyParams.Aptos variant_value:
                stream.WriteInt(2);
                FfiConverterUInt8.INSTANCE.Write(variant_value.ChainId, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Package, stream);
                break;
            case FamilyParams.Solana variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.Program, stream);
                break;
            case FamilyParams.Soroban variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.Passphrase, stream);
                FfiConverterString.INSTANCE.Write(variant_value.XlmSac, stream);
                break;
            case FamilyParams.Sui variant_value:
                stream.WriteInt(5);
                FfiConverterSequenceTypeEndpointConfig.INSTANCE.Write(variant_value.Graphql, stream);
                FfiConverterTypePolicy.INSTANCE.Write(variant_value.GraphqlPolicy, stream);
                break;
            case FamilyParams.Substrate variant_value:
                stream.WriteInt(6);
                FfiConverterSequenceTypeEndpointConfig.INSTANCE.Write(variant_value.Rpc, stream);
                FfiConverterTypePolicy.INSTANCE.Write(variant_value.RpcPolicy, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Genesis, stream);
                FfiConverterUInt16.INSTANCE.Write(variant_value.Ss58Prefix, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFamilyParams.Write()", value));
        }
    }
}







/// <summary>
/// The block of every decisive and decryption read (§9.4 requirement 3).
/// </summary>
internal record Finality {
    
    public record Finalized: Finality {}
    
    
    public record Depth (
        ulong V1
    ) : Finality {}
    

    
}

class FfiConverterTypeFinality : FfiConverterRustBuffer<Finality>{
    public static FfiConverterRustBuffer<Finality> INSTANCE = new FfiConverterTypeFinality();

    public override Finality Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new Finality.Finalized(
                );
            case 2:
                return new Finality.Depth(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFinality.Read()", value));
        }
    }

    public override int AllocationSize(Finality value) {
        switch (value) {
            case Finality.Finalized variant_value:
                return 4;
            case Finality.Depth variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.V1);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFinality.AllocationSize()", value));
        }
    }

    public override void Write(Finality value, BigEndianStream stream) {
        switch (value) {
            case Finality.Finalized variant_value:
                stream.WriteInt(1);
                break;
            case Finality.Depth variant_value:
                stream.WriteInt(2);
                FfiConverterUInt64.INSTANCE.Write(variant_value.V1, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeFinality.Write()", value));
        }
    }
}







/// <summary>
/// Where a part of a quote's gas figure came from (owner 2026-11-19), so the app and the operator see a figure not measured on
/// the chain.
/// </summary>
internal record GasFrom {
    
    /// <summary>
    /// a row of the chain profile, measured on that chain
    /// </summary>
    public record Chain: GasFrom {}
    
    
    /// <summary>
    /// a row of the named module table, the profile having opted in
    /// </summary>
    public record Module (
        string V1
    ) : GasFrom {}
    
    /// <summary>
    /// a row of the SCaaS reference table, the profile having opted in; not measured on this chain
    /// </summary>
    public record Reference: GasFrom {}
    
    
    /// <summary>
    /// the figure the app passed on the call
    /// </summary>
    public record App: GasFrom {}
    
    
    /// <summary>
    /// a native send's own estimate (or 21,000 for a plain transfer to an account without code)
    /// </summary>
    public record Estimate: GasFrom {}
    
    

    
}

class FfiConverterTypeGasFrom : FfiConverterRustBuffer<GasFrom>{
    public static FfiConverterRustBuffer<GasFrom> INSTANCE = new FfiConverterTypeGasFrom();

    public override GasFrom Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new GasFrom.Chain(
                );
            case 2:
                return new GasFrom.Module(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 3:
                return new GasFrom.Reference(
                );
            case 4:
                return new GasFrom.App(
                );
            case 5:
                return new GasFrom.Estimate(
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeGasFrom.Read()", value));
        }
    }

    public override int AllocationSize(GasFrom value) {
        switch (value) {
            case GasFrom.Chain variant_value:
                return 4;
            case GasFrom.Module variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.V1);
            case GasFrom.Reference variant_value:
                return 4;
            case GasFrom.App variant_value:
                return 4;
            case GasFrom.Estimate variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeGasFrom.AllocationSize()", value));
        }
    }

    public override void Write(GasFrom value, BigEndianStream stream) {
        switch (value) {
            case GasFrom.Chain variant_value:
                stream.WriteInt(1);
                break;
            case GasFrom.Module variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.V1, stream);
                break;
            case GasFrom.Reference variant_value:
                stream.WriteInt(3);
                break;
            case GasFrom.App variant_value:
                stream.WriteInt(4);
                break;
            case GasFrom.Estimate variant_value:
                stream.WriteInt(5);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeGasFrom.Write()", value));
        }
    }
}







/// <summary>
/// The holder's kind as the app read it from the registry (`singleKey` is per holder: spec set-auditor §4).
/// </summary>
internal enum HolderKind: int {
    /// <summary>
    /// a single key (one signer)
    /// </summary>
    SingleKey,
    /// <summary>
    /// a threshold (`msig`) UA
    /// </summary>
    Threshold,
    /// <summary>
    /// a native id with code
    /// </summary>
    Contract
}

class FfiConverterTypeHolderKind: FfiConverterRustBuffer<HolderKind> {
    public static FfiConverterTypeHolderKind INSTANCE = new FfiConverterTypeHolderKind();

    public override HolderKind Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return HolderKind.SingleKey;
            case 2: return HolderKind.Threshold;
            case 3: return HolderKind.Contract;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeHolderKind.Read()", value));
        }
    }

    public override int AllocationSize(HolderKind value) {
        return 4;
    }

    public override void Write(HolderKind value, BigEndianStream stream) {
        switch (value) {
            case HolderKind.SingleKey: stream.WriteInt(1); break;
            case HolderKind.Threshold: stream.WriteInt(2); break;
            case HolderKind.Contract: stream.WriteInt(3); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeHolderKind.Write()", value));
        }
    }
}







/// <summary>
/// What is known of an operation in flight (spec §13.5): none of it ends the operation.
/// </summary>
internal enum InFlight: int {
    /// <summary>
    /// signed and written, not sent yet
    /// </summary>
    Signed,
    /// <summary>
    /// a gateway queued it
    /// </summary>
    Queued,
    /// <summary>
    /// every gateway it went to refused it or could not be reached (one node's `dead` covers its own sends only)
    /// </summary>
    GivenUpByEveryNode,
    /// <summary>
    /// the self-relay transaction was accepted by an endpoint
    /// </summary>
    Sent,
    /// <summary>
    /// no endpoint accepted the self-relay transaction (`BroadcastRejected`, an outcome, never final)
    /// </summary>
    BroadcastRejected,
    /// <summary>
    /// the self-relay transaction is in a block, not final, or final and successful while the event is not read yet
    /// </summary>
    TxIncluded,
    /// <summary>
    /// the self-relay transaction is final and failed: the signed operation may still land by another relayer
    /// </summary>
    TxFinalFailed,
    /// <summary>
    /// the self-relay transaction was replaced
    /// </summary>
    TxReplaced,
    /// <summary>
    /// the signed operation's simulation from the payer reverted, failed or needed more gas than the confirmed quote: not sent
    /// by this SDK (owner 2026-11-19, ruling A). It is signed and may still land by another relayer until its nonce is spent or
    /// `validUntil` passes; `resend` tries again, a cancel of the lane's nonce ends it.
    /// </summary>
    SimRefused
}

class FfiConverterTypeInFlight: FfiConverterRustBuffer<InFlight> {
    public static FfiConverterTypeInFlight INSTANCE = new FfiConverterTypeInFlight();

    public override InFlight Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return InFlight.Signed;
            case 2: return InFlight.Queued;
            case 3: return InFlight.GivenUpByEveryNode;
            case 4: return InFlight.Sent;
            case 5: return InFlight.BroadcastRejected;
            case 6: return InFlight.TxIncluded;
            case 7: return InFlight.TxFinalFailed;
            case 8: return InFlight.TxReplaced;
            case 9: return InFlight.SimRefused;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeInFlight.Read()", value));
        }
    }

    public override int AllocationSize(InFlight value) {
        return 4;
    }

    public override void Write(InFlight value, BigEndianStream stream) {
        switch (value) {
            case InFlight.Signed: stream.WriteInt(1); break;
            case InFlight.Queued: stream.WriteInt(2); break;
            case InFlight.GivenUpByEveryNode: stream.WriteInt(3); break;
            case InFlight.Sent: stream.WriteInt(4); break;
            case InFlight.BroadcastRejected: stream.WriteInt(5); break;
            case InFlight.TxIncluded: stream.WriteInt(6); break;
            case InFlight.TxFinalFailed: stream.WriteInt(7); break;
            case InFlight.TxReplaced: stream.WriteInt(8); break;
            case InFlight.SimRefused: stream.WriteInt(9); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeInFlight.Write()", value));
        }
    }
}







/// <summary>
/// A key the SDK signs with, by reference (spec §5): the seed's open wallet holds it, or, for [`KeyRef::Key`], the platform's
/// authenticator (a passkey or a secure-element key, a row of the seed: owner 2026-11-19, S1).
/// </summary>
internal record KeyRef {
    
    public record Ua (
        string Seed,
        ushort Kind,
        uint Account,
        uint Index
    ) : KeyRef {}
    
    public record Native (
        string Seed,
        string Network,
        uint Index
    ) : KeyRef {}
    
    /// <summary>
    /// an imported classical key (spec §6.7, `vault.import_key`): the seed's vault `native-import:<network>:<index>`
    /// </summary>
    public record Imported (
        string Seed,
        string Network,
        uint Index
    ) : KeyRef {}
    
    /// <summary>
    /// the stored key row `id` of seed `seed` (`AccountRow::Key`: a passkey `webauthn-p256` with its credential id, a
    /// secure-element `p256` key with its handle), signing through the `Authenticator` (`external`)
    /// </summary>
    public record Key (
        string Seed,
        string Id
    ) : KeyRef {}
    
    /// <summary>
    /// the `msig` UA `ua` (`0x` + 64 hex) of the profile's registry, signing by the member slots named (CTR-UA-09, CTR-UA-38),
    /// each slot's key one this SDK holds; a minimal set of enabled and accepted slots of its current structure (CTR-UA-07,
    /// CTR-UA-37, CTR-UA-44). A slot's key is never an `Msig` itself (`Argument`).
    /// </summary>
    public record Msig (
        string UaValue,
        MsigSlot[] Slots
    ) : KeyRef {}
    
    /// <summary>
    /// a `bls12381-multi` (`0x0121`) group (plan Task 17): the seed's member key `ua_key(0x0121, account, index)` (EIP-2333:
    /// index 0) and the group's key data `d` (`0x` hex, spec 2026-11-19-bls12381-multi §2); the signer's id is the group's
    /// UA, its signature the members' aggregate ([`Op::submit_bls_multi`])
    /// </summary>
    public record BlsMulti (
        string Seed,
        uint Account,
        uint Index,
        string KeyData
    ) : KeyRef {}
    
    /// <summary>
    /// an operation another party signed and handed off (`Op::import_signed`, spec §27.5 (c)): its signer's subject id (`0x`
    /// hex); nothing in this SDK signs for it
    /// </summary>
    public record Signed (
        string Signer
    ) : KeyRef {}
    

    
}

class FfiConverterTypeKeyRef : FfiConverterRustBuffer<KeyRef>{
    public static FfiConverterRustBuffer<KeyRef> INSTANCE = new FfiConverterTypeKeyRef();

    public override KeyRef Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new KeyRef.Ua(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt16.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream)
                );
            case 2:
                return new KeyRef.Native(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream)
                );
            case 3:
                return new KeyRef.Imported(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream)
                );
            case 4:
                return new KeyRef.Key(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 5:
                return new KeyRef.Msig(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterSequenceTypeMsigSlot.INSTANCE.Read(stream)
                );
            case 6:
                return new KeyRef.BlsMulti(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 7:
                return new KeyRef.Signed(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeKeyRef.Read()", value));
        }
    }

    public override int AllocationSize(KeyRef value) {
        switch (value) {
            case KeyRef.Ua variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed)
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.Kind)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Account)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Index);
            case KeyRef.Native variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Network)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Index);
            case KeyRef.Imported variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Network)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Index);
            case KeyRef.Key variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Id);
            case KeyRef.Msig variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.UaValue)
                    + FfiConverterSequenceTypeMsigSlot.INSTANCE.AllocationSize(variant_value.Slots);
            case KeyRef.BlsMulti variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Account)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Index)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.KeyData);
            case KeyRef.Signed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Signer);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeKeyRef.AllocationSize()", value));
        }
    }

    public override void Write(KeyRef value, BigEndianStream stream) {
        switch (value) {
            case KeyRef.Ua variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                FfiConverterUInt16.INSTANCE.Write(variant_value.Kind, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Account, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Index, stream);
                break;
            case KeyRef.Native variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Network, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Index, stream);
                break;
            case KeyRef.Imported variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Network, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Index, stream);
                break;
            case KeyRef.Key variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Id, stream);
                break;
            case KeyRef.Msig variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.UaValue, stream);
                FfiConverterSequenceTypeMsigSlot.INSTANCE.Write(variant_value.Slots, stream);
                break;
            case KeyRef.BlsMulti variant_value:
                stream.WriteInt(6);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Account, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Index, stream);
                FfiConverterString.INSTANCE.Write(variant_value.KeyData, stream);
                break;
            case KeyRef.Signed variant_value:
                stream.WriteInt(7);
                FfiConverterString.INSTANCE.Write(variant_value.Signer, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeKeyRef.Write()", value));
        }
    }
}







