/// <summary>
/// One slot of an `msig` signature (`KeyRef::Msig`), as `MsigSlot`.
/// </summary>
internal record MsigSlotValue {
    
    /// <summary>
    /// the signing (or native) member at `index` signs with `key`
    /// </summary>
    public record Member (
        ushort Index,
        SlotKey Key
    ) : MsigSlotValue {}
    
    /// <summary>
    /// the `msig` member at `index` signs by its own slots, one level down
    /// </summary>
    public record Msig (
        ushort Index,
        MsigLeafValue[] Members
    ) : MsigSlotValue {}
    
    /// <summary>
    /// the slot at `index` already signed on another device: its `MemberSig` JSON as `Op::member_sign` returned it
    /// </summary>
    public record Signed (
        ushort Index,
        string MemberValue
    ) : MsigSlotValue {}
    

    
}

class FfiConverterTypeMsigSlotValue : FfiConverterRustBuffer<MsigSlotValue>{
    public static FfiConverterRustBuffer<MsigSlotValue> INSTANCE = new FfiConverterTypeMsigSlotValue();

    public override MsigSlotValue Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new MsigSlotValue.Member(
                    FfiConverterUInt16.INSTANCE.Read(stream),
                    FfiConverterTypeSlotKey.INSTANCE.Read(stream)
                );
            case 2:
                return new MsigSlotValue.Msig(
                    FfiConverterUInt16.INSTANCE.Read(stream),
                    FfiConverterSequenceTypeMsigLeafValue.INSTANCE.Read(stream)
                );
            case 3:
                return new MsigSlotValue.Signed(
                    FfiConverterUInt16.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeMsigSlotValue.Read()", value));
        }
    }

    public override int AllocationSize(MsigSlotValue value) {
        switch (value) {
            case MsigSlotValue.Member variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.Index)
                    + FfiConverterTypeSlotKey.INSTANCE.AllocationSize(variant_value.Key);
            case MsigSlotValue.Msig variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.Index)
                    + FfiConverterSequenceTypeMsigLeafValue.INSTANCE.AllocationSize(variant_value.Members);
            case MsigSlotValue.Signed variant_value:
                return 4
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.Index)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.MemberValue);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeMsigSlotValue.AllocationSize()", value));
        }
    }

    public override void Write(MsigSlotValue value, BigEndianStream stream) {
        switch (value) {
            case MsigSlotValue.Member variant_value:
                stream.WriteInt(1);
                FfiConverterUInt16.INSTANCE.Write(variant_value.Index, stream);
                FfiConverterTypeSlotKey.INSTANCE.Write(variant_value.Key, stream);
                break;
            case MsigSlotValue.Msig variant_value:
                stream.WriteInt(2);
                FfiConverterUInt16.INSTANCE.Write(variant_value.Index, stream);
                FfiConverterSequenceTypeMsigLeafValue.INSTANCE.Write(variant_value.Members, stream);
                break;
            case MsigSlotValue.Signed variant_value:
                stream.WriteInt(3);
                FfiConverterUInt16.INSTANCE.Write(variant_value.Index, stream);
                FfiConverterString.INSTANCE.Write(variant_value.MemberValue, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeMsigSlotValue.Write()", value));
        }
    }
}







/// <summary>
/// An operation's state (spec §13.5, CLI-SDK-18): terminal only on a chain fact from a decisive read at the profile's final
/// block.
/// </summary>
internal record OpState {
    
    /// <summary>
    /// the executed event of the operation's digest at or below the final block
    /// </summary>
    public record Landed (
        ulong Block,
        string Hash
    ) : OpState {}
    
    /// <summary>
    /// the lane's nonce spent at the final block without that event; a replaced native send
    /// </summary>
    public record Consumed: OpState {}
    
    
    /// <summary>
    /// an EVM native send final at or below the final block and reverted (owner 2026-11-18, ruling 4; the node's `reverted`)
    /// </summary>
    public record Reverted (
        ulong Block,
        string Hash
    ) : OpState {}
    
    /// <summary>
    /// `validUntil` below the final block's timestamp while the nonce is unspent
    /// </summary>
    public record Expired: OpState {}
    
    
    /// <summary>
    /// anything else, with what is known (never an end)
    /// </summary>
    public record InFlight (
        uniffi.scaas_sdk.InFlight Detail
    ) : OpState {}
    

    
}

class FfiConverterTypeOpState : FfiConverterRustBuffer<OpState>{
    public static FfiConverterRustBuffer<OpState> INSTANCE = new FfiConverterTypeOpState();

    public override OpState Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new OpState.Landed(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 2:
                return new OpState.Consumed(
                );
            case 3:
                return new OpState.Reverted(
                    FfiConverterUInt64.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 4:
                return new OpState.Expired(
                );
            case 5:
                return new OpState.InFlight(
                    FfiConverterTypeInFlight.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeOpState.Read()", value));
        }
    }

    public override int AllocationSize(OpState value) {
        switch (value) {
            case OpState.Landed variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.Block)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Hash);
            case OpState.Consumed variant_value:
                return 4;
            case OpState.Reverted variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.Block)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Hash);
            case OpState.Expired variant_value:
                return 4;
            case OpState.InFlight variant_value:
                return 4
                    + FfiConverterTypeInFlight.INSTANCE.AllocationSize(variant_value.Detail);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeOpState.AllocationSize()", value));
        }
    }

    public override void Write(OpState value, BigEndianStream stream) {
        switch (value) {
            case OpState.Landed variant_value:
                stream.WriteInt(1);
                FfiConverterUInt64.INSTANCE.Write(variant_value.Block, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Hash, stream);
                break;
            case OpState.Consumed variant_value:
                stream.WriteInt(2);
                break;
            case OpState.Reverted variant_value:
                stream.WriteInt(3);
                FfiConverterUInt64.INSTANCE.Write(variant_value.Block, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Hash, stream);
                break;
            case OpState.Expired variant_value:
                stream.WriteInt(4);
                break;
            case OpState.InFlight variant_value:
                stream.WriteInt(5);
                FfiConverterTypeInFlight.INSTANCE.Write(variant_value.Detail, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeOpState.Write()", value));
        }
    }
}







