        string NoteValue
    ) : PayBody {}
    
    public record CreditorRef (
        string CreditorRefValue,
        ulong DueDate
    ) : PayBody {}
    
    public record BoundCall (
        string ChainId,
        string Target,
        string CallHash
    ) : PayBody {}
    
    public record Ciphertext (
        string CiphertextValue
    ) : PayBody {}
    

    
}

class FfiConverterTypePayBody : FfiConverterRustBuffer<PayBody>{
    public static FfiConverterRustBuffer<PayBody> INSTANCE = new FfiConverterTypePayBody();

    public override PayBody Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new PayBody.None(
                );
            case 2:
                return new PayBody.Note(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 3:
                return new PayBody.CreditorRef(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 4:
                return new PayBody.BoundCall(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 5:
                return new PayBody.Ciphertext(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypePayBody.Read()", value));
        }
    }

    public override int AllocationSize(PayBody value) {
        switch (value) {
            case PayBody.None variant_value:
                return 4;
            case PayBody.Note variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.NoteValue);
            case PayBody.CreditorRef variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.CreditorRefValue)
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.DueDate);
            case PayBody.BoundCall variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.ChainId)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Target)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.CallHash);
            case PayBody.Ciphertext variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.CiphertextValue);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypePayBody.AllocationSize()", value));
        }
    }

    public override void Write(PayBody value, BigEndianStream stream) {
        switch (value) {
            case PayBody.None variant_value:
                stream.WriteInt(1);
                break;
            case PayBody.Note variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.NoteValue, stream);
                break;
            case PayBody.CreditorRef variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.CreditorRefValue, stream);
                FfiConverterUInt64.INSTANCE.Write(variant_value.DueDate, stream);
                break;
            case PayBody.BoundCall variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.ChainId, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Target, stream);
                FfiConverterString.INSTANCE.Write(variant_value.CallHash, stream);
                break;
            case PayBody.Ciphertext variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.CiphertextValue, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypePayBody.Write()", value));
        }
    }
