        public AppHandleForeign(string message): base(message) {}
    }
    
    public class AppLabelRefused: SdkException {
        public AppLabelRefused(string message): base(message) {}
    }
    
    public class AppKeyUsage: SdkException {
        public AppKeyUsage(string message): base(message) {}
    }
    
    public class AppArenaFull: SdkException {
        public AppArenaFull(string message): base(message) {}
    }
    
    public class KemKeyGone: SdkException {
        public KemKeyGone(string message): base(message) {}
    }
    
    public class ReceiverUnregistered: SdkException {
        public ReceiverUnregistered(string message): base(message) {}
    }
    
    public class RegistrationUaMismatch: SdkException {
        public RegistrationUaMismatch(string message): base(message) {}
    }
    
    public class RegistrationKindDisabled: SdkException {
        public RegistrationKindDisabled(string message): base(message) {}
    }
    
    public class RegistrationPopInvalid: SdkException {
        public RegistrationPopInvalid(string message): base(message) {}
    }
    
    public class RegistrationKemMissing: SdkException {
        public RegistrationKemMissing(string message): base(message) {}
    }
    
    public class AbiMismatch: SdkException {
        public AbiMismatch(string message): base(message) {}
    }
    
    /// <summary>
    /// No better name (a failed task included); carries nothing.
    /// </summary>
    public class Internal: SdkException {
        public Internal(string message): base(message) {}
    }
    
    /// <summary>
    /// An account row whose key (the same UA, native key or watched id) the seed lists already (owner 2026-11-18, Q1).
    /// </summary>
    public class AccountExists: SdkException {
        public AccountExists(string message): base(message) {}
    }
    
    /// <summary>
    /// A relayed operation's quote found no row of the gas table for its key (entry, domain kind, signer kind, fresh lane;
    /// owner 2026-11-18, ruling 1; owner 2026-11-19, ruling B).
    /// </summary>
    public class GasUnquoted: SdkException {
        public GasUnquoted(string message): base(message) {}
    }
    
    /// <summary>
    /// An operation's `validUntil` already past on the SDK's clock, or further ahead than the chain's window (owner 2026-11-19,
    /// T13b ruling 1).
    /// </summary>
    public class ValidUntilRefused: SdkException {
        public ValidUntilRefused(string message): base(message) {}
    }
    
    /// <summary>
    /// A confidential token the profile's factory does not catalogue as a token of the family, or whose code is not the
    /// factory's clone (spec §9.4 R5; owner 2026-11-19, C4).
    /// </summary>
    public class TokenUncatalogued: SdkException {
        public TokenUncatalogued(string message): base(message) {}
    }
    
    /// <summary>
    /// A UA whose registry record does not hold the key the read expects: the holder's leg not the handle's key, or a recipient's
    /// record not its UA's key (spec §9.4 R6; owner 2026-11-19, C4).
    /// </summary>
    public class LegKeyMismatch: SdkException {
        public LegKeyMismatch(string message): base(message) {}
    }
    
    /// <summary>
    /// A `SmartKeyAccount` entry's signer that is not a key of the account (owner 2026-11-19, P2).
    /// </summary>
    public class SignerNotAccountKey: SdkException {
        public SignerNotAccountKey(string message): base(message) {}
    }
    
    /// <summary>
    /// A PQZ token with the sealed opening (`proofSystemId` `PQZL_SPLIT_ID`, CTR-PQZ-38): its keys and debits are the `pqz3k`
    /// handles', not built in the SDK yet (P-T16-4, controller call 2026-11-19).
    /// </summary>
    public class PqzOpeningUnsupported: SdkException {
        public PqzOpeningUnsupported(string message): base(message) {}
    }
    
    /// <summary>
    /// An `msig` slot (or an inner leaf) that is not both enabled and accepted: it cannot sign (spec §15; M2, owner 2026-11-19).
    /// </summary>
    public class MsigSlotInactive: SdkException {
        public MsigSlotInactive(string message): base(message) {}
    }
    
    /// <summary>
    /// A gas table's verify row without `sig_bytes` (owner 2026-11-19, A4): every verify row states its signature's length.
    /// </summary>
    public class GasSigBytesMissing: SdkException {
        public GasSigBytesMissing(string message): base(message) {}
    }
    
    /// <summary>
    /// A self-relay whose gas, recomputed after signing from the signed calldata (the real signature's length; owner
    /// 2026-11-19, G3), exceeds `Limits::max_gas`: nothing written or sent.
    /// </summary>
    public class SignedGasAboveCap: SdkException {
        public SignedGasAboveCap(string message): base(message) {}
    }
    
    /// <summary>
    /// A gas table's row with `per_item` but no `item`, or the reverse (owner 2026-11-19, I1).
    /// </summary>
    public class GasItemUnpaired: SdkException {
        public GasItemUnpaired(string message): base(message) {}
    }
    
    /// <summary>
    /// A gas table's row whose `item` names no count the SDK reads (owner 2026-11-19, I1).
    /// </summary>
    public class GasItemUnknown: SdkException {
        public GasItemUnknown(string message): base(message) {}
    }
    
    /// <summary>
    /// An operation whose gas row grows with a count (`per_item`) that the SDK cannot read from the operation, or above
    /// 65,536 (owner 2026-11-19, I1): refused, never quoted without it.
    /// </summary>
    public class GasCountUnknown: SdkException {
        public GasCountUnknown(string message): base(message) {}
    }
    
    /// <summary>
    /// bls12381-multi (plan Task 17): the valid partials' weight is below the group's threshold
    /// </summary>
    public class BlsMultiBelowThreshold: SdkException {
        public BlsMultiBelowThreshold(string message): base(message) {}
    }
    
    /// <summary>
    /// A gas table with a key outside the format, at the top, on a row or inside a row's part (PR A review, finding 1): an
    /// unknown part is refused, never dropped from a quote.
    /// </summary>
    public class GasFieldUnknown: SdkException {
        public GasFieldUnknown(string message): base(message) {}
    }
    
    /// <summary>
    /// A registration of a kind whose home (`kindHome(kind)`) is another generation than the bound registry: that registry
    /// carries it verify-only, or not at all (spec 2026-11-19-registry-verify-only-kinds §12, CTR-UA-65); nothing is sent.
    /// </summary>
    public class RegistrationVerifyOnly: SdkException {
        public RegistrationVerifyOnly(string message): base(message) {}
    }
    
    /// <summary>
    /// A UA no generation of the bound registry's line holds (`holderOf(ua)` answers no holder, §11.1).
    /// </summary>
    public class UaUnregistered: SdkException {
        public UaUnregistered(string message): base(message) {}
    }
    
    /// <summary>
    /// A PQZ write or read of a UA whose record has no PQZ home on the bound registry's walk (`pqzHomeOf(ua)` 0, §11.2).
    /// </summary>
    public class PqzHomeNone: SdkException {
        public PqzHomeNone(string message): base(message) {}
    }
    
    /// <summary>
    /// An order, a cancel or a liquidity order naming a DEX that is not on the chain profile's list, or a wrap order whose
    /// wrapped token is not on its wrapper list (CLI-SGN-35): refused before anything is signed (plan T17).
    /// </summary>
    public class DexNotListed: SdkException {
        public DexNotListed(string message): base(message) {}
    }
    
    /// <summary>
    /// A PQZ auditor consent whose auditor is a native (address) key (controller call, owner auto-run 2026-11-19): a native id
    /// holds no PQZ key (CTR-UA-32), so the token refuses it on chain anyway; refused before anything is read or signed.
    /// </summary>
    public class PqzAuditorNative: SdkException {
        public PqzAuditorNative(string message): base(message) {}
    }
    
    /// <summary>
    /// A registration step whose gas (regular + state) is above half the chain's block gas limit (owner 2026-11-20): a
    /// registration carrying its PQZ key's proof above it goes in two steps, and a step above it alone is refused, nothing
    /// sent.
    /// </summary>
    public class GasAboveBlockShare: SdkException {
        public GasAboveBlockShare(string message): base(message) {}
    }
    
    /// <summary>
    /// An imported operation (spec §27.5 (c), owner 2026-11-22, Q-R3) of a kind the importer's family cannot show and check
    /// before sending, a confidential one (Zether, PQZ), or a struct or entry the family's rows do not hold.
    /// </summary>
    public class ImportKindRefused: SdkException {
        public ImportKindRefused(string message): base(message) {}
    }
    
    /// <summary>
    /// An imported pay or transfer whose `to` is none of the importer's ids.
    /// </summary>
    public class ImportNotPayee: SdkException {
        public ImportNotPayee(string message): base(message) {}
    }
    
    /// <summary>
    /// An imported operation whose signed `relayer` is bound to another address than the importer's payer (Soroban binds none).
    /// </summary>
    public class ImportRelayerBound: SdkException {
        public ImportRelayerBound(string message): base(message) {}
    }
    
    /// <summary>
    /// An imported operation with a fee to anyone: a hand-off is fee 0 (spec §27.5 (b)).
    /// </summary>
    public class ImportFeeRefused: SdkException {
        public ImportFeeRefused(string message): base(message) {}
    }
    
    /// <summary>
    /// An imported operation valid for less than the node's 120 s: its `validUntil` on the chain's clock (EVM, a Soroban
    /// pay), or its auth entry's expiry ledger (Soroban, a ledger at most each second).
    /// </summary>
    public class ImportExpired: SdkException {
        public ImportExpired(string message): base(message) {}
    }
    
    /// <summary>
    /// An imported operation already spent at the final height: its lane nonce (EVM), its host nonce or `pay_ref` entry
    /// (Soroban); it landed, or another operation took the nonce.
    /// </summary>
    public class ImportConsumed: SdkException {
        public ImportConsumed(string message): base(message) {}
    }
    
    /// <summary>
    /// An imported operation the simulation from the payer refused: the chain's judgement of the signature and the effect.
    /// </summary>
    public class ImportedOpRefused: SdkException {
        public ImportedOpRefused(string message): base(message) {}
    }
    
    /// <summary>
    /// An Arweave upload above the free tier, or refused there, with no payer: none configured, or the operator's node payer
    /// off (NODE-SPN-05; CLI-SDK-21).
    /// </summary>
    public class PayerUnavailable: SdkException {
        public PayerUnavailable(string message): base(message) {}
    }
    
    /// <summary>
    /// An Arweave upload the bundler refused for payment (HTTP 402): the user's own credits, or a payer's approval, are missing.
    /// </summary>
    public class PaymentRequired: SdkException {
        public PaymentRequired(string message): base(message) {}
    }
    
    /// <summary>
    /// An Arweave upload no bundler accepted, for a reason other than payment.
    /// </summary>
    public class UploadRejected: SdkException {
        public UploadRejected(string message): base(message) {}
    }
    
    /// <summary>
    /// A kept Arweave upload still unsettled after its last re-post (C20): shown; the bytes stay kept.
    /// </summary>
    public class UploadUnsettled: SdkException {
        public UploadUnsettled(string message): base(message) {}
    }
    
    /// <summary>
    /// A data item that is not one `scaas-ua` built: its verifying parser refused it, or it carries a target, an anchor or a
    /// tag, or its object is no bucket's (CLI-UAL-64): `scaas-ua`'s code for an item it built.
    /// </summary>
    public class ArweaveItem: SdkException {
        public ArweaveItem(string message): base(message) {}
    }
    
    /// <summary>
    /// A file or object above the platform's cap or the store's largest object (CLI-UAL-65): `scaas-ua`'s code.
    /// </summary>
    public class FileTooLarge: SdkException {
        public FileTooLarge(string message): base(message) {}
    }
    
    /// <summary>
    /// A file object or plaintext whose SHA-256 is not the signed one (CLI-UAL-65): `scaas-ua`'s code.
    /// </summary>
    public class FileHashMismatch: SdkException {
        public FileHashMismatch(string message): base(message) {}
    }
    
    /// <summary>
    /// a `*_blocking` call whose cancel token fired (spec §16.1, feature `sync-api`); the work goes on as a dropped future
    /// </summary>
    public class Cancelled: SdkException {
        public Cancelled(string message): base(message) {}
    }
    
    /// <summary>
    /// A `scaas-ua` wallet error, by its own code.
    /// </summary>
    public class Ua: SdkException {
        public Ua(string message): base(message) {}
    }
    
    /// <summary>
    /// A `scaas-rpc` error, by its own code (its text redacted by `scaas-rpc`, CLI-RPC-11).
    /// </summary>
    public class Rpc: SdkException {
        public Rpc(string message): base(message) {}
    }
    
}

