/// <summary>
/// A slot's key: `KeyRef` without the slots of an `msig` (a slot's key is never one, spec §7).
/// </summary>
internal record SlotKey {
    
    public record Ua (
        string Seed,
        ushort Kind,
        uint Account,
        uint Index
    ) : SlotKey {}
    
    public record Native (
        string Seed,
        string Network,
        uint Index
    ) : SlotKey {}
    
    public record Imported (
        string Seed,
        string Network,
        uint Index
    ) : SlotKey {}
    
    public record Key (
        string Seed,
        string Id
    ) : SlotKey {}
    
    /// <summary>
    /// refused at signing (`Argument`)
    /// </summary>
    public record Msig (
        string UaValue
    ) : SlotKey {}
    
    /// <summary>
    /// a `bls12381-multi` group's member key (as `KeyRef::BlsMulti`)
    /// </summary>
    public record BlsMulti (
        string Seed,
        uint Account,
        uint Index,
        string KeyData
    ) : SlotKey {}
    
    /// <summary>
    /// another party's signer (as `KeyRef::Signed`, a hand-off): never a slot's key, refused at signing
    /// </summary>
    public record Signed (
        string Signer
    ) : SlotKey {}
    

    
}

class FfiConverterTypeSlotKey : FfiConverterRustBuffer<SlotKey>{
    public static FfiConverterRustBuffer<SlotKey> INSTANCE = new FfiConverterTypeSlotKey();

    public override SlotKey Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new SlotKey.Ua(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt16.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream)
                );
            case 2:
                return new SlotKey.Native(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream)
                );
            case 3:
                return new SlotKey.Imported(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream)
                );
            case 4:
                return new SlotKey.Key(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 5:
                return new SlotKey.Msig(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 6:
                return new SlotKey.BlsMulti(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterUInt32.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 7:
                return new SlotKey.Signed(
                    FfiConverterString.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSlotKey.Read()", value));
        }
    }

    public override int AllocationSize(SlotKey value) {
        switch (value) {
            case SlotKey.Ua variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed)
                    + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.Kind)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Account)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Index);
            case SlotKey.Native variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Network)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Index);
            case SlotKey.Imported variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Network)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Index);
            case SlotKey.Key variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Id);
            case SlotKey.Msig variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.UaValue);
            case SlotKey.BlsMulti variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Seed)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Account)
                    + FfiConverterUInt32.INSTANCE.AllocationSize(variant_value.Index)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.KeyData);
            case SlotKey.Signed variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Signer);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSlotKey.AllocationSize()", value));
        }
    }

    public override void Write(SlotKey value, BigEndianStream stream) {
        switch (value) {
            case SlotKey.Ua variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                FfiConverterUInt16.INSTANCE.Write(variant_value.Kind, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Account, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Index, stream);
                break;
            case SlotKey.Native variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Network, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Index, stream);
                break;
            case SlotKey.Imported variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Network, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Index, stream);
                break;
            case SlotKey.Key variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Id, stream);
                break;
            case SlotKey.Msig variant_value:
                stream.WriteInt(5);
                FfiConverterString.INSTANCE.Write(variant_value.UaValue, stream);
                break;
            case SlotKey.BlsMulti variant_value:
                stream.WriteInt(6);
                FfiConverterString.INSTANCE.Write(variant_value.Seed, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Account, stream);
                FfiConverterUInt32.INSTANCE.Write(variant_value.Index, stream);
                FfiConverterString.INSTANCE.Write(variant_value.KeyData, stream);
                break;
            case SlotKey.Signed variant_value:
                stream.WriteInt(7);
                FfiConverterString.INSTANCE.Write(variant_value.Signer, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSlotKey.Write()", value));
        }
    }
}







/// <summary>
/// The call of a `SmartKeyAccount`'s `Execute` (spec §13.2): decoded, or opaque under the marker.
/// </summary>
internal record SmartCall {
    
    /// <summary>
    /// an ERC-20 `transfer(to, amount)` of `token` held by the account
    /// </summary>
    public record Transfer (
        string Token,
        string To,
        string Amount
    ) : SmartCall {}
    
    /// <summary>
    /// `account.initiateRecovery(key)`: the signer's account is `account`'s guardian (CTR-ACC-03)
    /// </summary>
    public record InitiateRecovery (
        string Account,
        SubjectKeyArgs Key
    ) : SmartCall {}
    
    /// <summary>
    /// any other call: `OpaqueCallRefused` without the marker
    /// </summary>
    public record Opaque (
        string Target,
        string Value,
        string Data,
        AllowOpaqueCall? Allow
    ) : SmartCall {}
    

    
}

class FfiConverterTypeSmartCall : FfiConverterRustBuffer<SmartCall>{
    public static FfiConverterRustBuffer<SmartCall> INSTANCE = new FfiConverterTypeSmartCall();

    public override SmartCall Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new SmartCall.Transfer(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream)
                );
            case 2:
                return new SmartCall.InitiateRecovery(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterTypeSubjectKeyArgs.INSTANCE.Read(stream)
                );
            case 3:
                return new SmartCall.Opaque(
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterString.INSTANCE.Read(stream),
                    FfiConverterOptionalTypeAllowOpaqueCall.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSmartCall.Read()", value));
        }
    }

    public override int AllocationSize(SmartCall value) {
        switch (value) {
            case SmartCall.Transfer variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Token)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.To)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Amount);
            case SmartCall.InitiateRecovery variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Account)
                    + FfiConverterTypeSubjectKeyArgs.INSTANCE.AllocationSize(variant_value.Key);
            case SmartCall.Opaque variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Target)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Value)
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.Data)
                    + FfiConverterOptionalTypeAllowOpaqueCall.INSTANCE.AllocationSize(variant_value.Allow);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSmartCall.AllocationSize()", value));
        }
    }

    public override void Write(SmartCall value, BigEndianStream stream) {
        switch (value) {
            case SmartCall.Transfer variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.Token, stream);
                FfiConverterString.INSTANCE.Write(variant_value.To, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Amount, stream);
                break;
            case SmartCall.InitiateRecovery variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.Account, stream);
                FfiConverterTypeSubjectKeyArgs.INSTANCE.Write(variant_value.Key, stream);
                break;
            case SmartCall.Opaque variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.Target, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Value, stream);
                FfiConverterString.INSTANCE.Write(variant_value.Data, stream);
                FfiConverterOptionalTypeAllowOpaqueCall.INSTANCE.Write(variant_value.Allow, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSmartCall.Write()", value));
        }
    }
}







/// <summary>
/// Where a reviewed value comes from (spec §13.1).
/// </summary>
internal enum Source: int {
    /// <summary>
    /// a field of the signed struct (or committed to by it, as a pay's `PayMeta`), decoded
    /// </summary>
    Signed,
    /// <summary>
    /// what the request named and the signed struct holds only in encrypted form (a confidential amount, recipient)
    /// </summary>
    Request,
    /// <summary>
    /// what the SDK chose or read: the contract, every token or market touched with its mark
    /// </summary>
    Derived
}

class FfiConverterTypeSource: FfiConverterRustBuffer<Source> {
    public static FfiConverterTypeSource INSTANCE = new FfiConverterTypeSource();

    public override Source Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1: return Source.Signed;
            case 2: return Source.Request;
            case 3: return Source.Derived;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSource.Read()", value));
        }
    }

    public override int AllocationSize(Source value) {
        return 4;
    }

    public override void Write(Source value, BigEndianStream stream) {
        switch (value) {
            case Source.Signed: stream.WriteInt(1); break;
            case Source.Request: stream.WriteInt(2); break;
            case Source.Derived: stream.WriteInt(3); break;
            default: throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSource.Write()", value));
        }
    }
}







/// <summary>
/// A store's failure; `Unexpected` is a foreign exception inside an app's implementation.
/// </summary>
internal class StoreException: UniffiException {
    StoreException() : base() {}
    StoreException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// `put_if`: the stored revision is not the expected one
    /// </summary>
    public class Conflict : StoreException {
        public Conflict() : base() {}
    }
    
    
    public class Io : StoreException {
        public Io() : base() {}
    }
    
    
    public class Unavailable : StoreException {
        public Unavailable() : base() {}
    }
    
    
    public class Unexpected : StoreException {
        public Unexpected() : base() {}
    }
    
    

    
}

class FfiConverterTypeStoreError : FfiConverterRustBuffer<StoreException>, CallStatusErrorHandler<StoreException> {
    public static FfiConverterTypeStoreError INSTANCE = new FfiConverterTypeStoreError();

    public override StoreException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new StoreException.Conflict();
            case 2:
                return new StoreException.Io();
            case 3:
                return new StoreException.Unavailable();
            case 4:
                return new StoreException.Unexpected();
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeStoreError.Read()", value));
        }
    }

    public override int AllocationSize(StoreException value) {
        switch (value) {

            case StoreException.Conflict variant_value:
                return 4;

            case StoreException.Io variant_value:
                return 4;

            case StoreException.Unavailable variant_value:
                return 4;

            case StoreException.Unexpected variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeStoreError.AllocationSize()", value));
        }
    }

    public override void Write(StoreException value, BigEndianStream stream) {
        switch (value) {
            case StoreException.Conflict variant_value:
                stream.WriteInt(1);
                break;
            case StoreException.Io variant_value:
                stream.WriteInt(2);
                break;
            case StoreException.Unavailable variant_value:
                stream.WriteInt(3);
                break;
            case StoreException.Unexpected variant_value:
                stream.WriteInt(4);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeStoreError.Write()", value));
        }
    }
}





/// <summary>
/// How an operation reaches the chain (spec §13.3).
/// </summary>
internal record SubmitPath {
    
    /// <summary>
    /// a gateway when the profile has one and the entry is one a gateway takes (door A), else a self-relay by `payer` when
    /// given, else `SubmitPathNone`
    /// </summary>
    public record Auto (
        KeyRef? Payer
    ) : SubmitPath {}
    
    /// <summary>
    /// the profile's gateways, the same body to each
    /// </summary>
    public record Gateway: SubmitPath {}
    
    
    /// <summary>
    /// an EIP-1559 transaction from the holder's own native EVM key, which pays the gas
    /// </summary>
    public record SelfRelay (
        KeyRef Payer
    ) : SubmitPath {}
    

    
}

class FfiConverterTypeSubmitPath : FfiConverterRustBuffer<SubmitPath>{
    public static FfiConverterRustBuffer<SubmitPath> INSTANCE = new FfiConverterTypeSubmitPath();

    public override SubmitPath Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new SubmitPath.Auto(
                    FfiConverterOptionalTypeKeyRef.INSTANCE.Read(stream)
                );
            case 2:
                return new SubmitPath.Gateway(
                );
            case 3:
                return new SubmitPath.SelfRelay(
                    FfiConverterTypeKeyRef.INSTANCE.Read(stream)
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSubmitPath.Read()", value));
        }
    }

    public override int AllocationSize(SubmitPath value) {
        switch (value) {
            case SubmitPath.Auto variant_value:
                return 4
                    + FfiConverterOptionalTypeKeyRef.INSTANCE.AllocationSize(variant_value.Payer);
            case SubmitPath.Gateway variant_value:
                return 4;
            case SubmitPath.SelfRelay variant_value:
                return 4
                    + FfiConverterTypeKeyRef.INSTANCE.AllocationSize(variant_value.Payer);
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSubmitPath.AllocationSize()", value));
        }
    }

    public override void Write(SubmitPath value, BigEndianStream stream) {
        switch (value) {
            case SubmitPath.Auto variant_value:
                stream.WriteInt(1);
                FfiConverterOptionalTypeKeyRef.INSTANCE.Write(variant_value.Payer, stream);
                break;
            case SubmitPath.Gateway variant_value:
                stream.WriteInt(2);
                break;
            case SubmitPath.SelfRelay variant_value:
                stream.WriteInt(3);
                FfiConverterTypeKeyRef.INSTANCE.Write(variant_value.Payer, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeSubmitPath.Write()", value));
        }
    }
}







/// <summary>
/// How a seed opens (spec §6.10). `Passkey` and `Platform` go through the seed's PRF envelope (plan T7).
/// </summary>
internal record Unlock: IDisposable  {
    
    public record Passphrase (
        SecretBytes V1
    ) : Unlock {}
    
    public record Passkey: Unlock {}
    
    
    public record Platform: Unlock {}
    
    

    
    public void Dispose() {
        switch (this) {
            case Unlock.Passphrase variant_value:
                FFIObjectUtil.DisposeAll(
                    variant_value.V1);
                break;
            case Unlock.Passkey variant_value:
                break;
            case Unlock.Platform variant_value:
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in Unlock.Dispose()", this));
        }
    }
    
}

class FfiConverterTypeUnlock : FfiConverterRustBuffer<Unlock>{
    public static FfiConverterRustBuffer<Unlock> INSTANCE = new FfiConverterTypeUnlock();

    public override Unlock Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new Unlock.Passphrase(
                    FfiConverterTypeSecretBytes.INSTANCE.Read(stream)
                );
            case 2:
                return new Unlock.Passkey(
                );
            case 3:
                return new Unlock.Platform(
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeUnlock.Read()", value));
        }
    }

    public override int AllocationSize(Unlock value) {
        switch (value) {
            case Unlock.Passphrase variant_value:
                return 4
                    + FfiConverterTypeSecretBytes.INSTANCE.AllocationSize(variant_value.V1);
            case Unlock.Passkey variant_value:
                return 4;
            case Unlock.Platform variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeUnlock.AllocationSize()", value));
        }
    }

    public override void Write(Unlock value, BigEndianStream stream) {
        switch (value) {
            case Unlock.Passphrase variant_value:
                stream.WriteInt(1);
                FfiConverterTypeSecretBytes.INSTANCE.Write(variant_value.V1, stream);
                break;
            case Unlock.Passkey variant_value:
                stream.WriteInt(2);
                break;
            case Unlock.Platform variant_value:
                stream.WriteInt(3);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeUnlock.Write()", value));
        }
    }
}






class FfiConverterOptionalUInt8: FfiConverterRustBuffer<byte?> {
    public static FfiConverterOptionalUInt8 INSTANCE = new FfiConverterOptionalUInt8();

    public override byte? Read(BigEndianStream stream) {
        if (stream.ReadByte() == 0) {
            return null;
        }
        return FfiConverterUInt8.INSTANCE.Read(stream);
    }

    public override int AllocationSize(byte? value) {
        if (value == null) {
            return 1;
        } else {
            return 1 + FfiConverterUInt8.INSTANCE.AllocationSize((byte)value);
        }
    }

    public override void Write(byte? value, BigEndianStream stream) {
        if (value == null) {
            stream.WriteByte(0);
        } else {
            stream.WriteByte(1);
            FfiConverterUInt8.INSTANCE.Write((byte)value, stream);
        }
    }
}




